-- Àrees de destreses del Quadern C1 de la JQCV (2. Objectius per àrees): Comprensió escrita,
-- Expressió i interacció escrites i Expressió i interacció orals, amb el mateix format que les del
-- B2 (20261013160000). L'objectiu 2.2 (Estructures lingüístiques) no és una àrea de pràctica: es
-- treballa en els continguts de llengua del C1 (20261014150000-190000) i és el que calibra la
-- rúbrica C1 de les redaccions (backend/src/services/examWritingEvaluator.ts). Són recursos del
-- nivell C1 (resources.difficulty) amb contingut C1:
--   * Comprensió escrita: assaigs i textos argumentatius, textos literaris, correspondència formal
--     i informal, textos contemporanis d'opinió, textos socials i professionals, i humor i ironia.
--   * Expressió escrita: redaccions que avalua el LLM amb la rúbrica del C1; el resum, els apunts i
--     la reelaboració porten el text o l'àudio de referència. Els àudios es generen amb el TTS
--     (backend/scripts/generate-practice-audio.ts) a /audio/practice/<type>-c1-<posició>.wav.
--   * Expressió oral: xats amb un personatge; el system_prompt es compon amb el del personatge,
--     unes pautes comunes del C1 i els objectius.
-- Tornar a aplicar el fitxer no duplica res: es reescriu el contingut C1.

DO $do$
DECLARE
  catalog jsonb := $data$[
  {"id": "ee24967a-5c71-5930-8c16-45365445871b", "category": "comprensio_escrita", "type": "c1_ce_assaig", "sort_order": 1, "title": "Assaig i opinió", "name": "Argumentacions abstractes", "content": "Seguix argumentacions abstractes en assajos i articles d'opinió, distingix les idees principals de les secundàries i valora'n les alternatives i les conclusions.", "icon": "🧠", "color": "#FFCCBC", "blocks": [{"passage": {"media": "text", "title": "Assaig: «El dret a ser oblidat (i el deure de recordar)»", "lines": [{"text": "Durant la major part de la història, oblidar era la norma i recordar, l'excepció. Calia esforç per a conservar: copiar a mà un manuscrit, gravar una làpida, guardar les cartes en una caixa de llanda. Allò que ningú no es preocupava de preservar desapareixia sense soroll, i eixa desaparició, tan natural com la caiguda de les fulles, permetia a les persones i a les comunitats començar de nou. Hui la relació s'ha invertit: recordar no costa res, perquè tot queda registrat per defecte, i és oblidar el que requerix una decisió deliberada, sovint un tràmit. Este canvi, que sembla merament tècnic, té conseqüències morals que encara no hem pensat prou."}, {"text": "La primera és que l'error es fa perpetu. Un comentari desafortunat escrit als dèsset anys, una fotografia d'una nit d'excessos o la notícia d'un procés judicial que va acabar en absolució continuen apareixent, intactes, quan algú busca el nostre nom vint anys després. La memòria humana és generosa perquè és imperfecta: difumina, reordena, matisa. L'arxiu digital, en canvi, no perdona perquè no envellix. I una societat que no permet que ningú deixe de ser qui va ser corre el risc de convertir la reinserció en una paraula buida."}, {"text": "Davant d'això, hi ha qui defén un dret a l'oblit ampli, que permeta a cada persona esborrar les dades que la perjudiquen. L'argument és atractiu, però té una esquerda evident: el que una persona vol oblidar pot ser exactament el que una altra necessita recordar. El polític que demana retirar una antiga declaració, l'empresa que vol fer desaparéixer una sanció o el veí que pretén esborrar la notícia d'una estafa també invoquen el dret a començar de nou. Si l'oblit depén només de la voluntat de l'interessat, l'arxiu es convertix en un aparador on cadascú exhibix la seua versió més favorable."}, {"text": "L'alternativa contrària, conservar-ho tot i fer-ho tot accessible en nom de la transparència, també té defensors, sobretot entre els qui recorden quantes vegades el poder ha manipulat la memòria col·lectiva. Però confon dues coses que convé separar: que un document existisca i que siga a l'abast de qualsevol, en qualsevol moment, amb una simple cerca. Els arxius històrics fa segles que resolen esta tensió amb una solució modesta: conserven, però regulen l'accés segons el temps transcorregut i la rellevància pública de les persones afectades."}, {"text": "Crec que eixa és la via més raonable, i no perquè siga un terme mitjà còmode, sinó perquè desplaça la pregunta. El dilema no és recordar o oblidar, sinó qui pot recordar què, i durant quant de temps. La informació sobre l'exercici d'un càrrec públic hauria de romandre visible; la vida privada d'un ciutadà anònim hauria d'anar perdent visibilitat a mesura que perd interés. No es tracta d'esborrar el passat, sinó de restituir-li la distància que la tecnologia li ha furtat."}, {"text": "Queda, és clar, una objecció de fons: qui decidix què és rellevant? No tinc una resposta definitiva, i desconfie de qui en tinga una. Però sospite que la pregunta mateixa ens obliga a recuperar una cosa que havíem oblidat, valga la paradoxa: que la memòria no és un magatzem, sinó un exercici de judici. Recordar bé no ha sigut mai recordar-ho tot."}]}, "exercises": [{"q": "Quina és la tesi de l'assaig?", "o": ["Cal regular l'accés a la informació segons el temps i la rellevància pública, no esborrar-la ni exposar-la sense límits", "Cal reconéixer un dret a l'oblit ampli que depenga només de la voluntat de cada persona", "Cal conservar tota la informació i fer-la accessible a tothom en nom de la transparència"], "e": "L'autor rebutja les dues alternatives extremes i defén la via dels arxius: «conserven, però regulen l'accés»."}, {"q": "Quin canvi descriu el primer paràgraf?", "o": ["Abans calia esforç per a recordar i ara el que requerix una decisió és oblidar", "Abans es recordava tot i ara la tecnologia fa que oblidem més de pressa", "Abans només les institucions guardaven documents i ara ho fan les persones"], "e": "«Hui la relació s'ha invertit: recordar no costa res [...] i és oblidar el que requerix una decisió deliberada.»"}, {"q": "Què vol dir l'autor amb «La memòria humana és generosa perquè és imperfecta»?", "o": ["Que, en difuminar i matisar els records, permet que les persones canvien", "Que la memòria humana conserva més informació que l'arxiu digital", "Que les persones recorden sobretot els moments positius del passat"], "e": "La contraposa a l'arxiu que «no perdona perquè no envellix»: l'oblit fa possible deixar de ser qui es va ser."}, {"q": "Quina «esquerda» troba l'autor en el dret a l'oblit ampli?", "o": ["Pot servir perquè cadascú amague informació que els altres necessiten conéixer", "És tècnicament impossible esborrar del tot una dada d'Internet", "Només el podrien exercir les persones amb recursos per a pagar advocats"], "e": "«El que una persona vol oblidar pot ser exactament el que una altra necessita recordar.»"}, {"q": "Quina funció tenen, en el tercer paràgraf, els exemples del polític, l'empresa i el veí?", "o": ["Il·lustrar com el dret a l'oblit es pot invocar per a ocultar fets d'interés públic", "Demostrar que el dret a l'oblit ja s'aplica amb èxit en molts casos", "Presentar les persones que més pateixen per culpa de l'arxiu digital"], "e": "Són idees secundàries que concreten l'objecció: tots «també invoquen el dret a començar de nou» per a amagar coses."}, {"q": "Quina distinció fa servir l'autor per a rebatre la conservació total?", "o": ["La diferència entre que un document existisca i que siga accessible a qualsevol en qualsevol moment", "La diferència entre els documents oficials i els documents privats", "La diferència entre la memòria individual i la memòria col·lectiva"], "e": "Diu que esta postura «confon dues coses que convé separar»: l'existència del document i l'accés immediat."}, {"q": "Què vol dir que la seua proposta «desplaça la pregunta»?", "o": ["Que transforma el dilema recordar/oblidar en una qüestió de qui pot accedir a què i durant quant de temps", "Que evita prendre partit i deixa la decisió en mans dels tribunals", "Que trasllada el problema dels ciutadans a les empreses tecnològiques"], "e": "«El dilema no és recordar o oblidar, sinó qui pot recordar què, i durant quant de temps.»"}, {"q": "Quina actitud mostra l'autor en l'últim paràgraf?", "o": ["Reconeix els límits de la seua proposta i desconfia de les respostes definitives", "Considera que la seua proposta resol definitivament el problema", "Renuncia a la seua tesi davant de l'objecció que planteja"], "e": "Admet una «objecció de fons» i diu: «No tinc una resposta definitiva, i desconfie de qui en tinga una», però manté la tesi."}]}, {"passage": {"media": "text", "title": "Opinió: «El mèrit, eixa ficció útil»", "lines": [{"text": "Cada mes de juny, quan es publiquen les notes d'accés a la universitat, els mitjans repetixen un ritual previsible: la fotografia de l'alumna amb la nota més alta, l'entrevista en què explica que s'alçava a les sis per a estudiar i el titular que ho resumix tot: «L'esforç té premi». No seré jo qui li regatege el mèrit. Però sí que voldria preguntar per tots els qui també s'alçaven a les sis i no ixen en la fotografia."}, {"text": "La meritocràcia és, probablement, la ficció més útil que han inventat les societats democràtiques. Útil perquè va substituir un ordre en què el cognom ho decidia tot per un altre en què, almenys en teoria, cadascú arriba on el porten les seues capacitats i el seu treball. Ningú amb dos dits de front voldria tornar a un món de privilegis hereditaris. El problema comença quan oblidem que és una ficció, és a dir, un ideal que orienta, i la prenem per una descripció exacta de la realitat."}, {"text": "Perquè el punt de partida no és mai el mateix. Qui ha crescut en una casa amb llibres, amb un escriptori propi i amb pares que podien pagar classes de repàs no ha tingut més mèrit que qui estudiava a la cuina mentre els germans menuts veien la televisió: ha tingut més sort. I la sort, a diferència del mèrit, no és cap virtut. Quan atribuïm l'èxit exclusivament a l'esforç, convertim una loteria parcial en un veredicte moral: els qui arriben s'ho han guanyat, i els qui no, alguna cosa deuen haver fet malament."}, {"text": "Les conseqüències d'eixe veredicte són doblement corrosives. Als guanyadors els inflen un orgull que els fa poc sensibles a la sort dels altres; als perdedors els carreguen, a més del fracàs, la humiliació de sentir-se'n culpables. No és estrany que en molts països el ressentiment polític haja crescut precisament entre els qui senten que el sistema els menysprea amb un somriure educat."}, {"text": "Hi ha qui proposa, davant d'això, abandonar la idea de mèrit i repartir les places per sorteig entre tots els qui superen un llindar mínim. La proposta té la virtut de l'honestedat, ja que reconeix obertament el paper de l'atzar, però em sembla un remei pitjor que la malaltia: renunciar a valorar el treball ben fet és també una manera de faltar-li al respecte. Uns altres, en l'extrem contrari, consideren que qualsevol correcció és una injustícia contra els millors. Tampoc no els done la raó: una cursa en què uns corren descalços no es fa més justa per cronometrar-la amb precisió."}, {"text": "La sortida, crec, passa per una meritocràcia conscient dels seus límits. Mantindre el mèrit com a criteri, però invertir de veritat per a igualar els punts de partida: beques que arriben a temps, escoles amb més recursos on més en falten, segones oportunitats per als qui van fallar als díhuit anys. I, sobretot, un canvi de to: que qui triomfa sàpia dir «he treballat molt» i, amb la mateixa naturalitat, «i he tingut sort»."}, {"text": "Potser el pròxim juny algun diari s'atrevirà a publicar, al costat de la foto de la millor nota, la de la cuina on estudiava algú altre. Seria una imatge menys inspiradora. També més honesta."}]}, "exercises": [{"q": "Quina és la tesi de l'article?", "o": ["El mèrit ha de continuar sent un criteri, però cal reconéixer el paper de la sort i igualar els punts de partida", "La meritocràcia és un engany que caldria substituir per un sistema de sorteig", "Qualsevol correcció de la meritocràcia és una injustícia contra els millors estudiants"], "e": "L'autor proposa «una meritocràcia conscient dels seus límits» i rebutja tant el sorteig com el rebuig a qualsevol correcció."}, {"q": "Per què l'autor qualifica la meritocràcia de «ficció útil»?", "o": ["Perquè és un ideal que orienta la societat, encara que no descriga exactament la realitat", "Perquè és una mentida que els governs utilitzen per a controlar la població", "Perquè només funciona en les novel·les i no en la vida real"], "e": "La definix com «un ideal que orienta» i critica que la prenguem «per una descripció exacta de la realitat»."}, {"q": "Què expressa la frase «No seré jo qui li regatege el mèrit»?", "o": ["Que l'autor no vol menysprear l'esforç de l'alumna premiada", "Que l'autor dubta que l'alumna haja estudiat realment tant", "Que l'autor vol negociar amb els mitjans el contingut de les notícies"], "e": "És una concessió: reconeix el mèrit de l'alumna abans d'introduir la seua crítica amb «Però»."}, {"q": "Quina idea il·lustra el contrast entre la casa amb llibres i la cuina?", "o": ["Que unes diferències d'origen es poden confondre amb diferències de mèrit", "Que estudiar a la cuina és més eficaç que fer-ho en un escriptori", "Que les famílies sense recursos no valoren prou els estudis"], "e": "Qui té més recursos «no ha tingut més mèrit [...]: ha tingut més sort»."}, {"q": "Què significa «convertim una loteria parcial en un veredicte moral»?", "o": ["Que jutgem moralment les persones per uns resultats que depenen en part de l'atzar", "Que els resultats acadèmics depenen totalment de la sort", "Que els jurats de les proves d'accés actuen de manera arbitrària"], "e": "Atribuir l'èxit només a l'esforç fa pensar que els qui no arriben «alguna cosa deuen haver fet malament»."}, {"q": "Com valora l'autor la proposta del sorteig?", "o": ["Li reconeix l'honestedat, però la rebutja perquè deixa de valorar el treball ben fet", "L'accepta com la millor solució, malgrat que és difícil d'aplicar", "La rebutja perquè considera que l'atzar no influïx en l'èxit"], "e": "«Té la virtut de l'honestedat [...] però em sembla un remei pitjor que la malaltia.»"}, {"q": "A qui respon l'autor amb la imatge de la cursa en què uns corren descalços?", "o": ["Als qui creuen que qualsevol correcció és injusta: la precisió en el mesurament no compensa la desigualtat de condicions", "Als qui proposen el sorteig: la sort no pot substituir la competició", "Als mitjans de comunicació: cal informar amb més precisió sobre les notes"], "e": "La imatge apareix just després de parlar dels qui «consideren que qualsevol correcció és una injustícia contra els millors»."}, {"q": "Quin efecte busca l'autor amb les dues frases finals?", "o": ["Contraposar el relat inspirador habitual amb una veritat menys agradable però més justa", "Demanar que els diaris deixen de publicar les notes d'accés", "Lamentar que els estudiants d'ara s'esforcen menys que els d'abans"], "e": "«Seria una imatge menys inspiradora. També més honesta.» Tanca l'article retornant a la imatge de la fotografia inicial."}]}]},
  {"id": "879e2f9f-6f82-5814-9d68-133702f29b63", "category": "comprensio_escrita", "type": "c1_ce_literaris", "sort_order": 2, "title": "Textos literaris", "name": "Conte i teatre", "content": "Interpreta el sentit figurat, el punt de vista, el to i les diferències d'estil en narrativa breu i teatre contemporanis.", "icon": "🎭", "color": "#D1C4E9", "blocks": [{"passage": {"media": "text", "title": "L'afinador", "lines": [{"text": "Eusebi Peris havia afinat pianos durant quaranta-un anys i sabia que les cases parlen abans que els amos. Aquella, al capdamunt d'un carrer costerut d'Ontinyent, li va parlar d'un silenci antic: persianes a mitja altura, un timbre que va sonar amb desgana, una catifa enrotllada al rebedor com si algú haguera començat una mudança i se n'haguera penedit. La senyora que li va obrir, menuda i molt dreta, no li va dir el seu nom. Va dir només: «És allí», i va assenyalar una porta amb la barbeta, com qui indica on dorm un animal que no convé despertar."}, {"text": "El piano era un vertical alemany dels anys vint, de fusta fosca, amb dos canelobres de llautó que ningú no havia mogut mai de lloc. Eusebi va alçar la tapa i va prémer el la central. El so va eixir esmorteït, mig to per davall del que calia, i ell va sentir aquella punxada professional que no se li havia curat amb l'edat: la de veure una cosa bonica desatesa. «Fa anys que no el toca ningú», va dir, més per a ell que per a la senyora. «Onze», va respondre ella des de la porta. No va entrar."}, {"text": "Va treballar durant hora i mitja amb la clau i les falques de feltre, corda a corda, amb eixa paciència que els clients confonen amb lentitud. A poc a poc el piano va anar recuperant la veu, com un malalt que torna a menjar. Quan va acabar, va tocar unes escales i, per costum, el començament d'un nocturn que sempre tocava per a comprovar els greus. Aleshores la senyora va entrar."}, {"text": "—No —va dir. No era una queixa; era una constatació—. No sona com sonava."}, {"text": "Eusebi va intentar explicar-li que ara estava a quatre-cents quaranta hertzs, com mana el diapasó, que abans estava baix, que tots els pianos desatesos es desafinen cap avall. Ella l'escoltava amb una cortesia impecable i absolutament impermeable. Quan ell va callar, va obrir un calaix del moble i en va traure una cinta de casset amb una etiqueta escrita a mà: «Nadal 2009». La va deixar en les seues mans sense dir res més."}, {"text": "Eusebi la va escoltar en el cotxe, aparcat davant de la porta, amb el motor apagat. Se sentien rialles, una copa que es trencava, una veu d'home que deia «Ara una de les nostres» i, després, el piano. El piano baix, un poc gangós, amb el si bemoll que ja aleshores vibrava. L'home tocava malament i amb una alegria enorme. Algú cantava desafinat i ningú no semblava adonar-se'n, o no importava."}, {"text": "Va tornar a pujar. Va demanar permís per a passar i va tornar a obrir la tapa. Durant una hora més va fer el que no havia fet mai en quaranta-un anys d'ofici: desafinar un piano amb tota la precisió de què era capaç, buscant no la nota justa sinó la nota d'aquell Nadal. La senyora, esta vegada, es va asseure en una cadira, a prop. Quan ell va tocar el la, ella va tancar els ulls."}, {"text": "No li va voler cobrar la segona hora. Ella va insistir, i ell li va dir que no havia fet cap faena: només havia tornat el piano al seu lloc. Mentre baixava l'escala, va pensar que els manuals d'afinació parlen molt de freqüències i molt poc de les cases on es toquen els pianos."}]}, "exercises": [{"q": "Des de quin punt de vista es conta la història?", "o": ["En tercera persona, centrada en la percepció i els pensaments de l'afinador", "En primera persona, per boca de la senyora de la casa", "En tercera persona, amb accés als pensaments de la senyora"], "e": "Coneixem el que Eusebi veu, sent i pensa («va pensar que els manuals...»), però mai el que pensa la senyora."}, {"q": "Què significa que «les cases parlen abans que els amos»?", "o": ["Que els detalls d'una casa revelen la situació dels qui hi viuen abans que ells en diguen res", "Que les cases velles fan sorolls que avisen de l'arribada dels visitants", "Que els amos de les cases solen ser persones de poques paraules"], "e": "Les persianes, el timbre i la catifa enrotllada li parlen d'«un silenci antic» abans que la senyora diga res."}, {"q": "Què suggerix la comparació «com qui indica on dorm un animal que no convé despertar»?", "o": ["Que el piano està carregat d'emocions que la senyora prefereix no remoure", "Que la senyora té por que el piano faça massa soroll", "Que a la casa hi ha un animal domèstic que dorm prop del piano"], "e": "La senyora evita acostar-se al piano («No va entrar»): és un objecte associat a un dolor adormit."}, {"q": "Què es pot inferir de la resposta «Onze» i de la cinta «Nadal 2009»?", "o": ["Que el piano va deixar de sonar quan va faltar l'home que el tocava", "Que la senyora va comprar el piano fa onze anys", "Que la senyora tocava el piano en les festes de Nadal"], "e": "L'home que toca en la gravació ja no hi és, i des d'aleshores ningú no ha tocat el piano."}, {"q": "Com escolta la senyora les explicacions tècniques d'Eusebi?", "o": ["Amb educació, però sense que la facen canviar gens d'opinió", "Amb interés, perquè no sabia que els pianos es desafinen", "Amb impaciència, i l'interromp abans que acabe"], "e": "«Una cortesia impecable i absolutament impermeable»: és amable, però les raons no li arriben."}, {"q": "Per què decidix Eusebi desafinar el piano?", "o": ["Perquè comprén que la senyora no vol la nota correcta, sinó el so lligat al seu record", "Perquè s'adona que havia comés un error tècnic en la primera afinació", "Perquè la senyora l'amenaça amb no pagar-li la faena"], "e": "Després d'escoltar la cinta busca «no la nota justa sinó la nota d'aquell Nadal»."}, {"q": "Quin efecte té l'expressió «desafinar un piano amb tota la precisió de què era capaç»?", "o": ["Crea una paradoxa que mostra l'ofici posat al servei de la memòria i no de la norma", "Mostra amb ironia que Eusebi no era un bon professional", "Indica que desafinar un piano és més fàcil que afinar-lo"], "e": "Unix dos termes contradictoris: tota la tècnica d'Eusebi s'usa per a reproduir un so «incorrecte» però estimat."}, {"q": "Quina idea transmet la reflexió final de l'afinador?", "o": ["Que la tècnica sovint ignora el valor afectiu que tenen les coses per a les persones", "Que els manuals d'afinació estan plens d'errors tècnics", "Que les cases antigues no són adequades per als pianos"], "e": "Els manuals parlen de «freqüències» i «molt poc de les cases»: és a dir, de les vides i els records que hi ha darrere."}]}, {"passage": {"media": "text", "title": "L'última nit de l'estació (fragment teatral)", "lines": [{"text": "(Sala d'espera d'una estació xicoteta de l'interior. Un rellotge de paret parat a les quatre i quart, un banc de fusta, una estufa apagada i cartells de la companyia amb els colors esvaïts. És de nit. ROSA, cap d'estació, d'uns seixanta anys, embala en caixes de cartó els objectes de l'oficina. Entra DAVID, de trenta i pocs, amb una motxilla i el mòbil en alt, buscant cobertura.)"}, {"text": "DAVID: Bona nit. El tren de les deu i vint... va amb retard?"}, {"text": "ROSA: (Sense girar-se.) Va amb molt de retard. Unes quantes dècades, si fa no fa."}, {"text": "DAVID: Perdone?"}, {"text": "ROSA: El de les deu i vint va passar ahir per última vegada. Des de hui, la línia està tancada. Ho va dir la ràdio, ho van dir els diaris, ho va dir el pregoner... Ho van dir tots menys el tren, que va passar com sempre, puntual, sense acomiadar-se de ningú."}, {"text": "DAVID: (Mira el mòbil, desconcertat.) Però en l'aplicació ix que..."}, {"text": "ROSA: L'aplicació. Clar. L'aplicació també es pensa que eixe rellotge funciona. (Assenyala el rellotge parat.) Es va parar el dia que es va jubilar el meu company, i vaig decidir que tenia raó."}, {"text": "DAVID: I ara com arribe jo a Xàtiva?"}, {"text": "ROSA: Hi ha un autobús que passa a les set del matí. Si no plou. Si plou, passa quan pot."}, {"text": "(Pausa. DAVID s'asseu en el banc, abatut. ROSA continua embalant. Agafa una gorra de cap d'estació, la mira i la deixa a banda, fora de les caixes.)"}, {"text": "DAVID: Vosté treballava ací?"}, {"text": "ROSA: Treballe ací fins a les dotze. Després seré una senyora amb una gorra. Trenta-quatre anys. Al principi érem quatre. Després, dos. Després, jo i una màquina de bitllets que s'empassava les monedes. Al final, la màquina feia la faena i jo li feia companyia."}, {"text": "DAVID: Deu ser dur."}, {"text": "ROSA: (S'atura. El mira per primera vegada.) Vosté és de ciutat, veritat?"}, {"text": "DAVID: De València. Per què?"}, {"text": "ROSA: Perquè a ciutat diuen «deu ser dur» com qui diu «bon profit». (Torna a les caixes.) No s'ofenga, no és un retret. Jo també ho diria."}, {"text": "DAVID: (Incòmode, prova una altra via.) Bé, diuen que ara la carretera és millor, que l'autobús és més ràpid..."}, {"text": "ROSA: Ah, sí. Molt més ràpid. Sobretot per als qui no l'agafen."}, {"text": "(Silenci. Se sent el vent. DAVID mira la gorra.)"}, {"text": "DAVID: Per què no la guarda amb la resta?"}, {"text": "ROSA: Perquè la resta és de la companyia. Ho tornaré tot, comptat i signat. La gorra és meua. (Pausa.) Bé, també és de la companyia. Però em van dir que la podia llançar, i una cosa que et deixen llançar ja és teua."}, {"text": "DAVID: (Somriu per primera vegada.) Això té tota la lògica del món."}, {"text": "ROSA: La lògica de l'estació. Ací hem aprés a fer molt amb molt poc. Ara aprendrem a fer-ho amb res."}, {"text": "(DAVID s'alça, agafa una caixa buida i comença a muntar-la, sense preguntar. ROSA el mira un moment i no diu res. Treballen en silenci.)"}, {"text": "DAVID: Sap què? Jo tampoc no tinc pressa. L'autobús no passa fins a les set."}, {"text": "ROSA: (Li allarga la cinta adhesiva.) Doncs a les set en punt el deixe a la parada. Però l'avise: jo no anuncie autobusos. Això sí que no."}, {"text": "(Fosc lent. L'última cosa que queda il·luminada és el rellotge parat.)"}]}, "exercises": [{"q": "Quina funció té l'acotació inicial (el rellotge parat, els colors esvaïts, l'estufa apagada)?", "o": ["Crear una atmosfera d'abandó i de temps detingut que anticipa el tancament", "Indicar que l'estació s'ha quedat sense electricitat aquella nit", "Situar l'acció en una època antiga, a principis del segle XX"], "e": "Els objectes parats, apagats o descolorits anticipen el final de la línia que Rosa revelarà després."}, {"q": "Què expressa Rosa amb «Va amb molt de retard. Unes quantes dècades»?", "o": ["Amb humor amarg, que el tren ja no passarà mai més", "Que el tren sempre arribava tard a eixa estació", "Que el tren de les deu i vint ha tingut una avaria greu"], "e": "És una ironia: no hi ha retard, sinó tancament definitiu de la línia."}, {"q": "Què transmet la frase «Ho van dir tots menys el tren, que va passar com sempre [...] sense acomiadar-se de ningú»?", "o": ["La tristesa d'un final que ha arribat sense cap cerimònia", "La queixa perquè el tren no va avisar amb el xiulet com era obligatori", "L'alegria que l'últim tren arribara puntual"], "e": "Personifica el tren: el final d'una cosa tan important passa com un dia qualsevol."}, {"q": "Què revela el comentari «la màquina feia la faena i jo li feia companyia»?", "o": ["Amb ironia, que la reducció de personal havia buidat de sentit el seu treball", "Que la màquina de bitllets funcionava millor que els treballadors", "Que Rosa se sentia sola i parlava amb la màquina"], "e": "Després de narrar com s'ha reduït la plantilla, inverteix els papers: ella ja és prescindible."}, {"q": "Per què Rosa compara «deu ser dur» amb «bon profit»?", "o": ["Perquè considera que és una fórmula de cortesia dita sense implicar-se de veritat", "Perquè pensa que la gent de ciutat sempre parla de menjar", "Perquè vol convidar David a sopar abans de tancar"], "e": "Són expressions convencionals que es diuen per costum; per això aclarix que no és un retret: «Jo també ho diria»."}, {"q": "Què implica la resposta «Sobretot per als qui no l'agafen»?", "o": ["Que les millores es valoren des de fora, per part de qui no patix la falta de servei", "Que l'autobús va més ràpid quan va buit", "Que la majoria de la gent del poble prefereix anar en cotxe"], "e": "Rosa desmunta l'argument de David: qui elogia l'autobús no depén d'ell."}, {"q": "Què revela el diàleg sobre la gorra?", "o": ["Que per a Rosa té un valor sentimental que la companyia no li reconeix", "Que Rosa vol quedar-se una cosa de la companyia sense permís", "Que la companyia li ha regalat la gorra com a homenatge"], "e": "Per a la companyia és un objecte per a llançar; per a ella, tota una vida: «ja és teua»."}, {"q": "Com evoluciona la relació entre els dos personatges al final del fragment?", "o": ["David passa de la incomoditat a una solidaritat silenciosa, i Rosa l'accepta sense dir-ho", "Rosa s'enfada amb David i li demana que isca de l'estació", "David convenç Rosa que el tancament de la línia és positiu"], "e": "Les acotacions ho mostren amb gestos: ell munta caixes «sense preguntar», ella «no diu res» i li allarga la cinta."}]}]},
  {"id": "36beaa25-5b9b-58ad-b7e2-1d65245e179f", "category": "comprensio_escrita", "type": "c1_ce_correspondencia", "sort_order": 3, "title": "Correspondència", "name": "Cartes formals i personals", "content": "Comprén correspondència formal i personal complexa i hi capta els matisos, els implícits, les al·lusions i les emocions.", "icon": "✉️", "color": "#F8BBD0", "blocks": [{"passage": {"media": "text", "title": "Resposta a una reclamació: la factura de l'aigua", "lines": [{"text": "Aigües de Benillosa, empresa mixta municipal · Servei d'Atenció a l'Usuari. Assumpte: resposta a la reclamació núm. 2026/0418 sobre la factura del segon trimestre."}, {"text": "Benvolguda senyora Mira:"}, {"text": "En primer lloc, li agraïm que ens haja fet arribar la seua reclamació i la documentació que l'acompanya, i li demanem disculpes pel retard d'esta resposta, que ha superat el termini de quinze dies hàbils que establix el nostre reglament. El retard es deu a la necessitat de fer una inspecció tècnica en el seu domicili, la qual cosa, tanmateix, no justifica que no l'informàrem a temps."}, {"text": "Hem examinat amb deteniment els fets que exposa. Segons les lectures del comptador, el consum registrat entre abril i juny va ser de 186 metres cúbics, una xifra que multiplica per sis el seu consum habitual i que, aplicada la tarifa per trams, dona lloc a l'import de 412,60 euros que vosté considera desproporcionat. La inspecció del 9 de setembre va confirmar l'existència d'una fuita en la canonada que connecta el comptador amb l'habitatge, ja reparada pel fontaner que vosté va contractar."}, {"text": "Pel que fa a la seua petició principal, que l'empresa assumisca la totalitat de l'import, lamentem comunicar-li que no hi podem accedir. D'acord amb l'article 34 del Reglament del servei, la conservació de les instal·lacions interiors, és a dir, les que se situen després del comptador, correspon a la persona titular del subministrament, i la fuita es localitzava precisament en este tram."}, {"text": "Això no obstant, el mateix reglament preveu que, en els casos de fuita oculta acreditada i reparada, l'excés de consum es facture a un preu reduït. Com que vosté complix els dos requisits, hem recalculat la factura aplicant als metres cúbics que superen la seua mitjana el preu del primer tram en lloc del més alt. L'import resultant és de 148,35 euros, és a dir, 264,25 euros menys que la factura original. Li adjuntem el detall del càlcul."}, {"text": "D'altra banda, vosté assenyala en el seu escrit que l'empresa hauria d'haver detectat l'anomalia, atés que disposem de comptadors de lectura remota. Hem de reconéixer que el sistema va generar una alerta de consum anòmal el 2 de maig i que, per una errada en el procediment intern, no se li va comunicar. Encara que això no altera la responsabilitat sobre la instal·lació, considerem que un avís a temps li hauria estalviat una part del consum. Per este motiu, i amb caràcter excepcional, hem decidit no aplicar-li el recàrrec per consum excessiu que preveu la tarifa, cosa que reduïx l'import final a 121,90 euros. Així mateix, hem revisat el protocol perquè estes alertes es notifiquen en un termini màxim de quaranta-huit hores."}, {"text": "Si està d'acord amb esta proposta, no cal que faça cap tràmit: la factura rectificada se li carregarà en el compte habitual, i pot sol·licitar que se li fraccione en tres mensualitats sense recàrrec. Si no hi està conforme, pot presentar una reclamació davant de l'Oficina Municipal d'Informació al Consumidor en el termini d'un mes a partir de la recepció d'este escrit, sense perjudici de les altres vies que li reconega la normativa."}, {"text": "Restem a la seua disposició per a qualsevol aclariment."}, {"text": "Atentament, Jaume Ribes Gisbert, cap del Servei d'Atenció a l'Usuari."}]}, "exercises": [{"q": "Quin és el propòsit principal d'esta carta?", "o": ["Respondre a una reclamació acceptant-la en part i rectificant la factura", "Comunicar a la clienta que la seua reclamació s'ha desestimat completament", "Informar d'una pujada de les tarifes de l'aigua per al pròxim trimestre"], "e": "Denega la petició principal, però rebaixa la factura de 412,60 a 121,90 euros."}, {"q": "Com tracta l'empresa el retard de la resposta?", "o": ["El reconeix i admet que la inspecció no l'excusa del tot", "El justifica plenament per la necessitat de fer una inspecció", "El nega, perquè considera que ha respost dins del termini"], "e": "La inspecció explica el retard, però «no justifica que no l'informàrem a temps»."}, {"q": "Per què l'empresa no assumix tot l'import, tal com demanava la clienta?", "o": ["Perquè la fuita estava en la instal·lació interior, que és responsabilitat de la titular", "Perquè la clienta no va presentar la factura del fontaner", "Perquè la clienta va reparar la fuita sense avisar l'empresa"], "e": "La fuita estava després del comptador, i eixe tram «correspon a la persona titular del subministrament»."}, {"q": "Quina funció té «Això no obstant» al començament del cinqué paràgraf?", "o": ["Introduïx una concessió que matisa la negativa anterior", "Introduïx la conclusió definitiva de la carta", "Introduïx un exemple que confirma la negativa anterior"], "e": "Després de denegar la petició, presenta una via que sí que afavorix la clienta: el preu reduït per fuita oculta."}, {"q": "Què reconeix l'empresa sobre els comptadors de lectura remota?", "o": ["Que el sistema va detectar l'anomalia, però per una errada interna no es va avisar la clienta", "Que el comptador de la clienta no tenia lectura remota", "Que el sistema no va detectar cap consum anòmal fins al setembre"], "e": "«El sistema va generar una alerta [...] el 2 de maig i [...] per una errada en el procediment intern, no se li va comunicar.»"}, {"q": "Per què l'empresa precisa que la segona rebaixa és «amb caràcter excepcional»?", "o": ["Per deixar clar que no reconeix cap responsabilitat sobre la fuita ni crea un precedent", "Perquè es tracta d'una oferta que només és vàlida durant un mes", "Perquè la clienta és usuària de l'empresa des de fa molts anys"], "e": "Insistix que l'errada «no altera la responsabilitat sobre la instal·lació»: és un gest, no una obligació."}, {"q": "Si la clienta accepta la proposta, què ha de fer?", "o": ["Res: se li cobraran 121,90 euros en el compte, i pot demanar pagar-los en tres mesos", "Presentar una sol·licitud a l'oficina de consum en el termini d'un mes", "Pagar 148,35 euros en l'oficina de l'empresa"], "e": "«No cal que faça cap tràmit»; l'import final és de 121,90 euros i es pot fraccionar sense recàrrec."}, {"q": "Quin to predomina en la carta?", "o": ["Formal i conciliador: ferm en la norma, però disposat a reconéixer errors", "Distant i burocràtic: es limita a citar el reglament", "Col·loquial i afectuós: intenta fer-se amiga de la clienta"], "e": "Demana disculpes, admet l'errada i oferix rebaixes, però manté la negativa basada en el reglament."}]}, {"passage": {"media": "text", "title": "Una carta després de la novel·la", "lines": [{"text": "Estimada Lluïsa:"}, {"text": "He tardat tres setmanes a escriure't, i no perquè m'haja faltat temps. Ho he començat quatre vegades. La primera em va eixir massa llarga; la segona, massa curta; la tercera parlava tant del temps que fa a Gandia que pareixia un butlletí meteorològic. La quarta l'he esborrada sense rellegir-la, que és la manera més sàvia d'esborrar les coses."}, {"text": "Vaig llegir la novel·la en dos dies. Ja saps que no he llegit res en dos dies des que van nàixer els xiquets, així que pots prendre-t'ho com un elogi, o com un símptoma. És bona, Lluïsa. Molt bona. Les crítiques tenen raó, i ho dic jo, que mai no he tingut gaire paciència amb les crítiques. Hi ha pàgines sobre la mare de la protagonista que m'han fet plorar en el tren, davant d'un senyor que, molt educadament, va fer com si no ho veiera."}, {"text": "I ara, la part difícil. Supose que ja t'imaginaves que reconeixeria la Marta. No crec que calguera canviar-li el nom: qualsevol que ens coneguera als vint anys sabria qui és la xica que va deixar la carrera a mitges per a seguir un músic a Berlín i va tornar sis mesos després amb una maleta i cap explicació. Fins i tot li has deixat la jaqueta groga. Això no sé si agrair-t'ho."}, {"text": "No t'escric per a retraure-t'ho. O no només. Una part de mi entén que les històries són de qui les escriu, i que si algú havia de contar aquella primavera, millor tu, que l'has contada amb tendresa, que no algú que l'haguera contada amb la boca torta. Però una altra part, la que encara es despertava de nit l'any noranta-huit, no pot evitar preguntar-se per què no m'ho vas dir abans de publicar-la. Una telefonada. Un «escolta, Carme, he escrit una cosa». Ho haguera entés. Potser no a la primera, però ho haguera entés."}, {"text": "Hi ha una cosa que la novel·la no conta bé, i no és culpa teua, perquè tu no la podies saber. La Marta no va tornar de Berlín perquè el músic la deixara. Va tornar perquè una nit, en una cabina, va sentir la teua veu dient que la teua mare estava malalta, i va comprendre que hi havia coses que no es poden acompanyar per telèfon. El músic, per cert, toca ara en una orquestra de cambra i té més panxa que el meu cunyat. Ho dic sense rancor. Bé, amb el just."}, {"text": "Els xiquets estan bé. El gran ja parla de deixar la carrera; li he dit que, si se'n va a Berlín, s'emporte una jaqueta que no siga groga. No ho ha entés, és clar."}, {"text": "Vine per Pasqua, si vols. La casa de la platja continua tenint aquella finestra que no tanca bé i que tu deies que era l'única honesta de la casa. Podem parlar de la novel·la o no parlar-ne. Podem parlar del temps, que ja saps que se'm dona bé."}, {"text": "Una abraçada, i enhorabona. De veritat."}, {"text": "Carme"}, {"text": "P. S.: La pròxima vegada que em poses en un llibre, almenys fes-me més alta."}]}, "exercises": [{"q": "Quin és el motiu principal de la carta?", "o": ["Reaccionar davant d'una novel·la en què Carme s'ha reconegut, amb elogis i un retret", "Felicitar Lluïsa per un premi literari que acaba de guanyar", "Demanar a Lluïsa que retire la novel·la de les llibreries"], "e": "Carme elogia la novel·la, explica que s'hi ha reconegut en la Marta i li retrau que no l'avisara."}, {"q": "Què revela el primer paràgraf sobre l'estat d'ànim de Carme?", "o": ["Que li ha costat trobar el to adequat per a una carta delicada", "Que ha estat massa ocupada per a escriure abans", "Que no li ha agradat gens la novel·la de la seua amiga"], "e": "Diu que no li ha faltat temps i que l'ha començada quatre vegades: el problema és què dir i com."}, {"q": "Què insinua Carme quan diu que la lectura en dos dies pot ser «un elogi, o com un símptoma»?", "o": ["Que la novel·la l'ha afectada personalment, no sols com a lectora", "Que ha estat malalta i ha tingut temps per a llegir", "Que la novel·la és tan curta que es llig molt de pressa"], "e": "Un «símptoma» suggerix que l'ha llegida amb ansietat perquè s'hi reconeixia."}, {"q": "Qui és la Marta?", "o": ["Un personatge de la novel·la inspirat en la mateixa Carme", "La germana de Carme, que viu a Berlín", "La protagonista de la novel·la, inspirada en la mare de Lluïsa"], "e": "«Supose que ja t'imaginaves que reconeixeria la Marta»: la història de Berlín i la jaqueta groga són de Carme."}, {"q": "Què li retrau realment Carme a Lluïsa?", "o": ["No haver-li dit res abans de publicar la novel·la", "Haver contat la història amb poca tendresa", "Haver-li canviat el nom al personatge"], "e": "«No pot evitar preguntar-se per què no m'ho vas dir abans de publicar-la.» Reconeix que l'ha contada «amb tendresa»."}, {"q": "Què desvela Carme que la novel·la no sabia?", "o": ["Que va tornar de Berlín per estar al costat de Lluïsa quan la mare d'esta estava malalta", "Que el músic la va abandonar per una altra dona", "Que va acabar la carrera a Berlín abans de tornar"], "e": "Va tornar en sentir que «la teua mare estava malalta»: un gest d'amistat que Lluïsa ignorava."}, {"q": "Com s'ha d'entendre «Ho dic sense rancor. Bé, amb el just»?", "o": ["Carme reconeix amb ironia que encara li queda un poc de ressentiment", "Carme afirma que no sent cap rancor cap al músic", "Carme admet que està enfadada sobretot amb Lluïsa"], "e": "Es corregix a si mateixa amb humor: el rancor no ha desaparegut del tot."}, {"q": "Què expressa la invitació del penúltim paràgraf?", "o": ["La voluntat de mantindre l'amistat i de parlar amb sinceritat, sense pressionar", "El desig de no tornar a parlar mai més de la novel·la", "La intenció de vendre la casa de la platja abans de Pasqua"], "e": "L'al·lusió a la finestra «honesta» i el «Podem parlar de la novel·la o no parlar-ne» oferixen una trobada oberta i sincera."}]}]},
  {"id": "6b30ce1c-e5f8-53f0-98c2-5ef3a3fd1b65", "category": "comprensio_escrita", "type": "c1_ce_contemporanis", "sort_order": 4, "title": "Textos contemporanis", "name": "Columnes, reportatges i entrevistes", "content": "Identifica l'estratègia, el punt de vista i les opinions personals de qui escriu en textos de temàtica contemporània.", "icon": "🗞️", "color": "#C8E6C9", "blocks": [{"passage": {"media": "text", "title": "Columna: «Cinc estreles per al meu dentista»", "lines": [{"text": "Fa uns dies, el meu dentista, un home seriós que fins ara només m'havia demanat que obrira la boca, em va demanar una altra cosa: que el valorara en internet. M'ho va dir amb la mà encara dins de la meua boca, de manera que no vaig poder negar-m'hi, i ho va acompanyar d'un somriure que tenia alguna cosa de súplica. Eixa vesprada, amb les genives adormides, vaig descobrir que la clínica tenia quatre-centes ressenyes i una nota de 4,9. Vaig pensar, no sé si amb tendresa o amb pena, en el pobre 0,1 que faltava."}, {"text": "No és un cas aïllat. Hui ens demanen que puntuem el fontaner, el repartidor, l'hotel, el curs de ioga, la gestoria i fins i tot la visita al museu. Hi ha restaurants que regalen les postres a canvi d'una opinió i empreses que avaluen els treballadors segons les estreles que reben dels clients. Durant molt de temps, vaig pensar que tot això era inofensiu, una manera moderna i democràtica de recomanar-nos coses els uns als altres, com feien les nostres mares a la porta del forn. Reconec que encara ho pense en part: gràcies a les ressenyes he evitat més d'un hostal infame."}, {"text": "Però la comparació amb el forn fa aigües per tots els costats. La veïna que et recomanava un fuster el coneixia, i tu coneixies la veïna: sabies si era exigent o si s'acontentava amb poc. Les ressenyes, en canvi, són veus sense cara que sumem com si foren equivalents. I, sobretot, la recomanació de la porta del forn no tenia conseqüències per al fuster, més enllà de guanyar o perdre un client. Ara una mitjana de 4,3 pot fer que un algoritme amague un negoci o que una empresa retalle el sou d'un repartidor que ha tingut la mala sort de portar un paquet a un client malhumorat."}, {"text": "El resultat és una economia de l'amabilitat obligatòria. Els professionals ja no aspiren a fer bé la faena, sinó a no deixar cap escletxa per on puga colar-se una estrela de menys. Somriuen més, però no sé si treballen millor. I els clients, sense adonar-nos-en, hem acceptat un paper incòmode: el de supervisors gratuïts d'uns treballadors que no són nostres. Exercim un poder minúscul però real, i ho fem sovint entre dues parades de metro, amb el polze i de mal humor."}, {"text": "Hi ha qui diu que la solució és més transparència: ressenyes verificades, filtres contra les falsificacions, sistemes més sofisticats. No m'oposaré a res d'això, però sospite que el problema no és tècnic. El problema és que hem convertit totes les relacions en transaccions que cal qualificar, com si la confiança es poguera mesurar en una escala de l'u al cinc. Una societat que necessita puntuar-ho tot és, potser, una societat que ja no es fia de ningú."}, {"text": "Per això he pres una decisió modesta, que no canviarà el món però que em deixa dormir: no puntuaré ningú que no m'haja fet una cosa extraordinària, per a bé o per a mal. Al dentista, finalment, sí que li vaig escriure la ressenya. Li vaig posar cinc estreles, és clar: no tinc prou valor per a ser coherent amb la boca oberta. Però hi vaig escriure una sola frase: «Fa bé la seua faena, i això hauria de ser suficient». M'agradaria pensar que ell, que és un home seriós, ho entendrà."}]}, "exercises": [{"q": "Quina estratègia fa servir l'autor per a començar la columna?", "o": ["Partix d'una anècdota personal i humorística que introduïx el tema", "Presenta dades estadístiques sobre l'ús de les ressenyes", "Cita l'opinió d'un expert en comerç electrònic"], "e": "Comença amb l'episodi del dentista que li demana una valoració «amb la mà encara dins de la meua boca»."}, {"q": "Què suggerix la frase «vaig pensar […] en el pobre 0,1 que faltava»?", "o": ["Que la pressió per la nota perfecta fa que fins i tot una dècima semble una falta", "Que la clínica tenia, en realitat, una mala reputació", "Que l'autor pensava posar-li una nota baixa al dentista"], "e": "Amb ironia, l'autor compadix la dècima que separa el 4,9 del 5, com si fóra un defecte."}, {"q": "Què fa l'autor en el segon paràgraf, abans de desenvolupar la crítica?", "o": ["Una concessió: reconeix que les ressenyes tenen alguna utilitat", "Defén que les ressenyes són perjudicials en tots els casos", "Explica que ell no n'ha consultades mai"], "e": "«Reconec que encara ho pense en part: gràcies a les ressenyes he evitat més d'un hostal infame.»"}, {"q": "Què vol dir que la comparació amb el forn «fa aigües per tots els costats»?", "o": ["Que no s'aguanta, perquè les dues situacions són molt diferents", "Que és una comparació molt encertada i clara", "Que els forns antics tenien problemes de goteres"], "e": "Sentit figurat: la comparació falla; tot seguit l'autor n'explica les diferències."}, {"q": "Segons l'autor, què distingix sobretot la ressenya actual de la recomanació tradicional?", "o": ["Que ve de desconeguts i pot tindre conseqüències greus per al treballador", "Que és més sincera perquè és anònima", "Que arriba a molta menys gent"], "e": "Les ressenyes són «veus sense cara» i una mitjana baixa pot fer que «una empresa retalle el sou d'un repartidor»."}, {"q": "Quin paper diu l'autor que hem acceptat els clients?", "o": ["El de supervisors gratuïts de treballadors d'altres empreses", "El de víctimes de professionals poc amables", "El d'experts que milloren la qualitat dels servicis"], "e": "«El de supervisors gratuïts d'uns treballadors que no són nostres.»"}, {"q": "Quina és la tesi central de la columna?", "o": ["La mania de puntuar-ho tot convertix les relacions en transaccions i revela falta de confiança", "Cal millorar tècnicament els sistemes de ressenyes per a evitar falsificacions", "Les ressenyes falses són l'únic problema real del comerç actual"], "e": "«El problema no és tècnic […]. Una societat que necessita puntuar-ho tot és, potser, una societat que ja no es fia de ningú.»"}, {"q": "Quin to té el final, quan l'autor posa cinc estreles al dentista?", "o": ["Autoirònic: admet que no és capaç d'aplicar del tot la seua pròpia crítica", "Triomfal: celebra que ha guanyat la batalla contra el sistema", "Penedit: reconeix que les ressenyes són, al capdavall, positives"], "e": "«No tinc prou valor per a ser coherent amb la boca oberta»: es riu de la seua pròpia incoherència, tot i que manté la idea amb la frase escrita."}]}, {"passage": {"media": "text", "title": "Entrevista: «No estem més sols, estem desconnectats»", "lines": [{"text": "Remei Albiol arriba a l'entrevista amb deu minuts de retard i una disculpa sincera: s'ha entretingut parlant amb el quiosquer. No és una anècdota menor en algú que ha dedicat cinc anys a estudiar la soledat no desitjada a les ciutats. El seu assaig, Finestres tancades, s'ha convertit en un èxit inesperat, potser perquè posa paraules a una cosa que molts sentim i pocs confessem. Parlem amb ella en una cafeteria del seu barri, on el cambrer ja sap què vol abans que ho demane."}, {"text": "—Diuen que vivim l'època més connectada de la història i, alhora, la més solitària. És una contradicció? —És una frase molt bonica per a un titular, però no la compre del tot. No tinc clar que siguem més solitaris que els nostres avis; el que ha canviat és la forma de la soledat. Abans era sobretot rural i associada a la vellesa. Ara la trobes també en un xic de vint-i-cinc anys que treballa des de casa en un pis compartit, amb tres companys a qui saluda per missatge des de l'habitació del costat."}, {"text": "—Què distingix la soledat no desitjada d'estar sol? —Que no l'has triada. Hi ha persones que viuen soles i tenen una vida plena, i n'hi ha que viuen en famílies nombroses i se senten com un moble. La soledat no és una dada del padró, és la distància entre les relacions que tens i les que voldries tindre. Per això les polítiques que només compten quantes persones viuen soles s'equivoquen de diana."}, {"text": "—En el llibre és molt crítica amb l'urbanisme. —Crítica no; diria que impacient. Fa dècades que dissenyem ciutats per a anar d'un lloc a un altre, no per a estar-hi. Hem tret els bancs de les places perquè no s'hi asseguera ningú «indesitjable», i ara resulta que no s'hi asseu ningú. Hem substituït la botiga del barri per la gran superfície, i la plaça per un centre comercial on no pots parar-te sense comprar. Després ens estranyem que la gent no es conega."}, {"text": "—Hi ha qui li retrau que idealitza el passat, el poble on tothom es coneixia. —Ho sé, i m'ho he preguntat moltes vegades. El poble on tothom es coneixia també era el poble on tothom et vigilava, i moltes dones, per exemple, hi vivien una soledat ben dura que ningú no anomenava així. No vull tornar arrere. Vull que recuperem allò que funcionava, els espais de trobada casual, sense recuperar el control social que l'acompanyava."}, {"text": "—I què pot fer una persona, a banda d'esperar que canvien les ciutats? —Coses xicotetes que semblen ridícules. Saludar el veí de l'ascensor. Comprar el pa sempre en el mateix lloc. Acceptar que una conversa intranscendent no és una pèrdua de temps. Sé que sona a manual d'autoajuda i em fa un poc de vergonya dir-ho, però les dades són tossudes: les relacions febles, eixes que menyspreem, són les que més ens protegixen de l'aïllament."}, {"text": "Quan acabem, Albiol no s'alça de seguida. Es queda uns minuts parlant amb el cambrer sobre la filla d'ell, que acaba de començar la universitat, i li pregunta si ja s'ha fet amics. Pot ser una casualitat. Però em costa no llegir-ho com l'última resposta de l'entrevista."}]}, "exercises": [{"q": "Quina funció té, en l'entradeta, la menció del retard per culpa del quiosquer?", "o": ["Anticipar que l'entrevistada practica allò que defén", "Criticar la falta de puntualitat de l'entrevistada", "Descriure el barri on viu l'entrevistada"], "e": "«No és una anècdota menor en algú que ha dedicat cinc anys a estudiar la soledat»: la conversa casual és el que ella recomana."}, {"q": "Com reacciona Albiol davant de la primera pregunta?", "o": ["Matisa la premissa: no hi ha més soledat, sinó una forma diferent de soledat", "L'accepta sense reserves i hi aporta dades", "Es nega a respondre perquè la troba massa periodística"], "e": "«No la compre del tot […]; el que ha canviat és la forma de la soledat.»"}, {"q": "Segons l'entrevistada, què és la soledat no desitjada?", "o": ["La distància entre les relacions que tens i les que voldries tindre", "El fet de viure sol en un habitatge", "Un problema que afecta sobretot la gent gran dels pobles"], "e": "«No és una dada del padró, és la distància entre les relacions que tens i les que voldries tindre.»"}, {"q": "Què vol dir que certes polítiques «s'equivoquen de diana»?", "o": ["Que apunten a un objectiu equivocat", "Que no tenen prou pressupost", "Que es basen en dades falses del padró"], "e": "Comptar qui viu sol no mesura la soledat no desitjada; per tant, l'objectiu està mal triat."}, {"q": "Per què corregix l'adjectiu «crítica» per «impacient»?", "o": ["Per a presentar la seua postura com una urgència de canvi més que com un rebuig", "Perquè en realitat està d'acord amb l'urbanisme actual", "Perquè vol evitar qualsevol polèmica amb els urbanistes"], "e": "Manté la crítica als models de ciutat, però la formula com a pressa perquè es corregisquen."}, {"q": "Quina ironia hi ha en «ara resulta que no s'hi asseu ningú»?", "o": ["Una mesura pensada contra uns pocs ha acabat expulsant tothom", "La gent preferix seure en les terrasses dels bars", "Els bancs nous són massa incòmodes per a seure-hi"], "e": "Es van traure els bancs perquè no hi seguera ningú «indesitjable», i el resultat és que les places es buiden."}, {"q": "Com respon a l'acusació d'idealitzar el passat?", "o": ["Hi reconeix part de raó i distingix allò que vol recuperar del que no", "Nega haver parlat mai dels pobles en el llibre", "Afirma que la vida als pobles era millor en tots els sentits"], "e": "Admet el «control social» del poble i diu: «Vull que recuperem allò que funcionava […] sense recuperar el control social»."}, {"q": "Quin punt de vista adopta la periodista en el paràgraf final?", "o": ["Interpreta el gest de l'entrevistada com una confirmació de les seues idees", "Critica que l'entrevistada es quede parlant en compte d'anar-se'n", "Posa en dubte la sinceritat de tot el que ha dit l'entrevistada"], "e": "«Em costa no llegir-ho com l'última resposta de l'entrevista»: la conversa amb el cambrer il·lustra les «relacions febles»."}]}]},
  {"id": "9ec82648-b8f9-583a-89ae-426d6b4d708f", "category": "comprensio_escrita", "type": "c1_ce_professional", "sort_order": 5, "title": "Textos professionals", "name": "Informes, actes i comunicats", "content": "Capta detalls subtils i l'actitud, explícita o implícita, de qui escriu en textos d'àmbit social i professional.", "icon": "💼", "color": "#D7CCC8", "blocks": [{"passage": {"media": "text", "title": "Informe intern: la prova pilot de la jornada de quatre dies", "lines": [{"text": "Informe intern. De: Lídia Soriano Peris, directora de Persones. A: Comité de Direcció de Taulells Montcabrer, SL. Assumpte: avaluació de la prova pilot de jornada de quatre dies en el departament d'administració i en l'equip de disseny (gener-juny de 2026). Caràcter: confidencial."}, {"text": "1. Antecedents. Tal com es va acordar en la reunió del comité del 14 de novembre passat, amb el vot favorable de la majoria dels seus membres, durant el primer semestre de l'any s'ha aplicat de manera experimental una jornada de trenta-dues hores setmanals, distribuïdes en quatre dies i sense reducció salarial, a les 38 persones que integren els dos equips esmentats. La prova no s'ha estés a la planta de producció, per raons que ja es van exposar en el seu moment i que este informe no pretén reobrir."}, {"text": "2. Resultats. Els indicadors de productivitat del departament d'administració s'han mantingut estables: el termini mitjà de tramitació de factures ha passat de 6,2 a 6,4 dies, una variació que, segons el Departament Financer, «no és significativa». L'equip de disseny ha lliurat les catorze col·leccions previstes en el calendari, dues d'elles amb una setmana d'antelació. L'absentisme per baixa mèdica de curta durada s'ha reduït un 41 % respecte del mateix període de l'any anterior, i en l'enquesta interna, que han respost 35 de les 38 persones, el 91 % es declara «molt satisfet» amb la nova organització. Cal dir, per honestedat, que una enquesta d'estes característiques difícilment podia oferir un altre resultat."}, {"text": "3. Incidències. S'han detectat dificultats en l'atenció als clients els divendres, dia en què la major part de la plantilla no treballava. Tot i que es va establir un torn de guàrdia, s'han registrat set queixes formals, quatre de les quals procedixen del mateix distribuïdor, la relació comercial amb el qual ja presentava problemes abans de la prova. D'altra banda, algunes persones de la planta de producció han manifestat, a través del comité d'empresa, el seu malestar per haver quedat excloses de la mesura. Este departament entén que eixe malestar és comprensible i que caldrà gestionar-lo amb una explicació clara, no amb silenci."}, {"text": "4. Costos. El Departament Financer ha calculat un cost addicional de 23.000 euros en hores extraordinàries i substitucions durant el semestre. Esta direcció no qüestiona la xifra, però sí que considera oportú recordar que el càlcul no inclou l'estalvi derivat de la reducció de les baixes, que, segons les estimacions del nostre departament, seria d'un orde de magnitud semblant. Seria convenient que totes dues xifres es presentaren conjuntament en la pròxima reunió del comité."}, {"text": "5. Conclusions i proposta. A la vista de les dades, i amb la prudència que exigix una mostra reduïda i un període curt, este departament proposa prorrogar la prova sis mesos més, en les mateixes condicions, i encarregar-ne una avaluació externa que aporte una mirada independent. No es proposa, de moment, l'extensió a la planta de producció, però sí la creació d'un grup de treball amb el comité d'empresa per a estudiar-hi fórmules alternatives de flexibilitat. Una decisió de no continuar seria legítima; tanmateix, convindria que es prenguera sobre la base de tots els indicadors, i no només d'alguns."}, {"text": "Vila-real, 3 de juliol de 2026."}]}, "exercises": [{"q": "Què suggerix l'incís «per raons que ja es van exposar en el seu moment i que este informe no pretén reobrir»?", "o": ["Que l'exclusió de la planta de producció va ser una qüestió polèmica que l'autora preferix no tornar a debatre", "Que les raons de l'exclusió eren secretes i no es poden revelar", "Que l'autora desconeix per què es va excloure la planta de producció"], "e": "L'autora evita expressament un debat que es va tancar abans; el malestar posterior de la planta confirma que era un tema delicat."}, {"q": "Per què cita entre cometes la valoració del Departament Financer «no és significativa»?", "o": ["Per a atribuir-la a un altre departament, la qual cosa la fa més creïble", "Per a mostrar que no està d'acord amb eixa valoració", "Per a reproduir el text d'una norma legal"], "e": "Que la dada favorable la reconega un departament diferent, i que a més és el que calcula els costos, reforça l'argument de l'autora."}, {"q": "Què revela el comentari «Cal dir, per honestedat, que una enquesta d'estes característiques difícilment podia oferir un altre resultat»?", "o": ["Que l'autora relativitza una dada favorable perquè la responen les persones beneficiades", "Que l'enquesta s'havia manipulat per a obtindre bons resultats", "Que la plantilla va respondre l'enquesta amb por de represàlies"], "e": "Qui gaudix de la mesura quasi sempre se'n declara satisfet; l'autora es mostra rigorosa i guanya credibilitat."}, {"q": "Quin matís introduïx l'autora sobre les set queixes formals?", "o": ["Que més de la meitat venen d'un client amb qui ja hi havia problemes", "Que totes eren injustificades i s'han arxivat", "Que les va presentar el comité d'empresa"], "e": "«Quatre de les quals procedixen del mateix distribuïdor, la relació comercial amb el qual ja presentava problemes abans de la prova.»"}, {"q": "Quina actitud mostra davant del malestar de la planta de producció?", "o": ["L'entén i demana que s'hi responga amb transparència", "El considera injustificat i proposa ignorar-lo", "Proposa estendre immediatament la mesura a la planta"], "e": "«Eixe malestar és comprensible i […] caldrà gestionar-lo amb una explicació clara, no amb silenci.»"}, {"q": "Què insinua l'autora en l'apartat de costos?", "o": ["Que la xifra del Departament Financer dona una visió parcial dels efectes econòmics", "Que la xifra de 23.000 euros és falsa", "Que el cost de la prova és impossible d'assumir"], "e": "No qüestiona la xifra, però recorda que «no inclou l'estalvi derivat de la reducció de les baixes»."}, {"q": "Quina proposta fa l'informe?", "o": ["Prorrogar la prova sis mesos amb una avaluació externa", "Estendre la jornada de quatre dies a tota l'empresa", "Donar per acabada la prova i tornar a l'horari anterior"], "e": "«Proposa prorrogar la prova sis mesos més […] i encarregar-ne una avaluació externa.»"}, {"q": "Quina intenció té l'última frase de les conclusions?", "o": ["Advertir, amb cortesia, que alguns membres podrien decidir basant-se només en les dades desfavorables", "Reconéixer que les dades del seu departament són incompletes", "Demanar que la decisió es prenga en votació secreta"], "e": "«No només d'alguns»: l'autora preveu una oposició centrada en els costos i les queixes, i ho diu de manera indirecta."}]}, {"passage": {"media": "text", "title": "Acta d'una assemblea extraordinària de la Societat Musical", "lines": [{"text": "Acta de l'assemblea general extraordinària de socis i sòcies de la Societat Musical La Unió de Sant Joan de la Ribera. Data: 26 de setembre de 2026. Hora: 20.00 h, en segona convocatòria. Lloc: saló d'actes de la seu social. Assistents: 87 socis i sòcies de ple dret, més 12 representats per delegació. Presidix: Vicent Mompó Ferrer, president. Actua com a secretària: Empar Grau Llinares."}, {"text": "Orde del dia: 1. Informació sobre l'oferta de compra de l'edifici del Casino presentada per l'empresa Ribera Hospitality, SL. 2. Debat i, si escau, votació. 3. Precs i preguntes."}, {"text": "1. El president informa que l'empresa esmentada ha oferit 1,4 milions d'euros per l'edifici del Casino, propietat de la Societat des de 1921, amb la intenció de convertir-lo en un hotel. Segons explica, l'operació permetria saldar el préstec pendent de la reforma de l'escola de música i construir una seu nova, més moderna i accessible, en un solar cedit per l'Ajuntament als afores del poble. El president qualifica l'oferta d'«una oportunitat que no tornarà», afig que la junta directiva hi dona suport per unanimitat i recorda que el termini per a respondre acaba el 15 d'octubre."}, {"text": "2. S'obri el torn de paraules. La sòcia Rosa Bellver, clarinetista de la banda des de fa quaranta anys, pregunta per què la documentació de l'oferta no s'ha posat a disposició dels socis fins dos dies abans de l'assemblea. El president respon que es tracta d'una informació delicada i que la junta ha actuat amb la discreció que el cas requeria. La senyora Bellver diu que respecta la discreció, però que els socis no són «uns estranys a qui cal protegir de la informació». Diversos assistents aplaudixen."}, {"text": "El soci Joan Martí, tresorer de la Societat entre 2014 i 2022, advertix que el solar proposat no disposa encara de la qualificació urbanística necessària i que, fins que no s'aprove la modificació del planejament, no hi ha cap garantia que la seu nova es puga construir en el termini previst. Pregunta on assajaria la banda durant eixe període. El president respon que «ja es buscarà una solució». El senyor Martí demana que la resposta conste literalment en l'acta, i així es fa."}, {"text": "La sòcia Marta Ivars, de 23 anys, membre de la secció de percussió, intervé per a dir que entén l'estima per l'edifici, però que el Casino no complix la normativa d'accessibilitat, que la sala d'assaig s'ha quedat xicoteta i que, si la Societat vol tindre futur, haurà de prendre decisions difícils. Demana que no es plantege el debat com una lluita entre joves i vells. La intervenció és rebuda amb un silenci respectuós."}, {"text": "Després de més de dues hores de debat, el soci Joan Martí proposa ajornar la votació fins que s'haja aprovat la qualificació del solar i es dispose d'un informe tècnic independent sobre el valor de l'edifici. Sotmesa a votació la proposta d'ajornament, obté 61 vots a favor, 34 en contra i 4 abstencions. Queda, per tant, aprovada. El president expressa la seua «decepció» i anuncia que comunicarà el resultat a l'empresa, tot i que dubta que l'oferta es mantinga."}, {"text": "3. Precs i preguntes. No n'hi ha. I, sense més assumptes a tractar, el president alça la sessió a les 22.40 h, de la qual cosa, com a secretària, en done fe."}]}, "exercises": [{"q": "Quins elements del primer punt suggerixen que la junta volia tancar l'operació de pressa?", "o": ["La insistència en el termini del 15 d'octubre i en el fet que l'oportunitat «no tornarà»", "La data de compra de l'edifici, l'any 1921", "La cessió d'un solar per part de l'Ajuntament"], "e": "El president presenta l'oferta com a irrepetible i recorda que hi ha un termini molt pròxim per a respondre."}, {"q": "Què critica implícitament Rosa Bellver?", "o": ["Que la junta no ha sigut prou transparent amb els socis", "Que el preu oferit per l'edifici és massa baix", "Que els músics joves no participen en la Societat"], "e": "Pregunta per què la documentació s'ha donat «dos dies abans de l'assemblea»."}, {"q": "Quin efecte té la frase de Bellver «uns estranys a qui cal protegir de la informació»?", "o": ["Gira en contra de la junta l'argument de la discreció", "Elogia la prudència amb què ha actuat la junta", "Demana que les persones no sòcies abandonen la sala"], "e": "Accepta la paraula «discreció», però mostra que, aplicada als mateixos socis, és absurda. Els aplaudiments indiquen que molts hi estan d'acord."}, {"q": "Per què Joan Martí demana que la resposta del president conste literalment en l'acta?", "o": ["Per a deixar constància de la falta de concreció de la junta en un punt clau", "Perquè la solució proposada li sembla excel·lent", "Perquè la secretària havia resumit malament la intervenció"], "e": "«Ja es buscarà una solució» no respon la pregunta; deixar-ho escrit en l'acta servix per a demanar-ne responsabilitats més avant."}, {"q": "Quin risc principal assenyala Joan Martí?", "o": ["Que la banda es quede sense lloc per a assajar si la seu nova no es pot construir a temps", "Que l'hotel moleste els veïns del centre del poble", "Que el préstec de l'escola de música augmente"], "e": "El solar encara no té la qualificació urbanística i «no hi ha cap garantia que la seu nova es puga construir en el termini previst»."}, {"q": "Quin paper té la intervenció de Marta Ivars en el debat?", "o": ["Matisa el debat: valora l'edifici, però aporta raons a favor del canvi", "S'oposa frontalment a la venda del Casino", "Demana un informe tècnic independent abans de votar"], "e": "Entén «l'estima per l'edifici», però recorda els problemes d'accessibilitat i d'espai, i demana no enfrontar joves i vells."}, {"q": "Què es pot deduir del resultat de la votació?", "o": ["Que una majoria clara no compartix la pressa de la junta, sense rebutjar necessàriament la venda", "Que l'assemblea rebutja definitivament la venda de l'edifici", "Que la proposta de la junta ha obtingut el suport majoritari"], "e": "Es vota l'ajornament (61 a favor), no la venda: l'assemblea vol més garanties abans de decidir."}, {"q": "Quina actitud mostra el president al final de l'assemblea?", "o": ["Contrarietat, amb un retret implícit perquè l'ajornament podria fer perdre l'oferta", "Satisfacció per la participació dels socis", "Indiferència davant del resultat"], "e": "Expressa la seua «decepció» i diu que «dubta que l'oferta es mantinga», cosa que responsabilitza indirectament l'assemblea."}]}]},
  {"id": "40691289-0777-595d-94a9-8e7f540a3f45", "category": "comprensio_escrita", "type": "c1_ce_ironia", "sort_order": 6, "title": "Llegir entre línies", "name": "Sàtira, ironia i equívocs", "content": "Capta l'humor, la ironia i els equívocs, i inferix actituds i intencions que no es diuen explícitament.", "icon": "🎭", "color": "#F8BBD0", "blocks": [{"passage": {"media": "text", "title": "Carta a la directora: «Gràcies per la plaça nova»", "lines": [{"text": "Senyora directora: Escric per a expressar el meu agraïment més sincer a l'Ajuntament per la nova plaça Major, inaugurada el mes passat amb banda de música, discursos i una cinta que, per cert, és l'única cosa que hi hem vist a l'ombra des d'aleshores."}, {"text": "Durant anys, els veïns vam haver de suportar quatre plataners centenaris que no feien altra cosa que donar ombra, embrutar el terra amb fulles a la tardor i atraure pardals que, amb una falta d'educació evident, cantaven sense demanar permís. Gràcies a la valentia del consistori, tot això s'ha acabat. Ara tenim una esplanada de granit gris de nou-cents metres quadrats, neta, diàfana i, sobretot, fàcil de netejar, que, segons el projecte, «posa en valor l'espai públic». Encara no he entés quin valor tenia abans, però és evident que ara en té un altre."}, {"text": "Vull destacar també l'audàcia estètica dels bancs de formigó, dissenyats, imagine, per a fomentar l'esperit de superació. A les quatre de la vesprada d'agost, seure-hi és una experiència que recomane a tots els regidors, preferentment amb pantalons curts. L'altre dia vaig veure un turista que hi va deixar un ou i, al cap de deu minuts, se'l menjava fregit. Potser exagere, però no gaire."}, {"text": "Hi ha qui s'ha queixat que la plaça està buida. És injust. A les onze del matí, quan el termòmetre de la farmàcia marca 41 graus, s'hi pot observar una activitat intensa: les persones majors la travessen corrent, en diagonal, d'una vorera a l'altra, amb una agilitat que no els coneixíem. Ningú no podrà dir que l'Ajuntament no fa res per l'envelliment actiu."}, {"text": "Els xiquets, això sí, han deixat de jugar-hi a pilota, però no crec que siga culpa de la plaça. Segurament és perquè ara tenen més deures, o perquè preferixen les pantalles, que, com tothom sap, són la causa de tots els mals de la joventut. També ha desaparegut la tertúlia de jubilats que es reunia cada vesprada davall del plataner gros. Alguns diuen que s'ha traslladat al bar de la cantonada, que té aire condicionat. Jo crec que, simplement, han madurat."}, {"text": "Sé que el regidor d'Urbanisme va declarar que els arbres «es plantaran en una segona fase», quan les arrels ja no posen en perill les canalitzacions noves. Celebre la previsió. Tinc setanta-quatre anys i una salut acceptable, de manera que, si la segona fase arriba amb la mateixa rapidesa que la primera i els arbres creixen al ritme habitual, és molt possible que els meus nets puguen asseure's a la seua ombra. Jo, per si de cas, ja m'he comprat un para-sol."}, {"text": "Per a acabar, una proposta modesta: que l'any que ve l'Ajuntament organitze en la plaça un concurs de fregir ous al sol. Seria un esdeveniment únic en la comarca, atrauria turisme i, per fi, donaria a la plaça l'ús per al qual sembla haver sigut concebuda. Atentament, Pasqual Garrigues Sendra, veí de la plaça Major."}]}, "exercises": [{"q": "Què insinua l'autor quan diu que la cinta de la inauguració és «l'única cosa que hi hem vist a l'ombra»?", "o": ["Que la plaça nova no té cap ombra", "Que la inauguració es va fer de nit", "Que la cinta era de mala qualitat"], "e": "La broma anticipa la crítica central de la carta: la plaça, sense arbres, és un forn."}, {"q": "Com presenta l'autor els plataners en el segon paràgraf?", "o": ["Enumera com a defectes allò que, en realitat, eren virtuts", "Com un perill real per als vianants", "Amb indiferència, com un detall sense importància"], "e": "Retrau als arbres que «no feien altra cosa que donar ombra»: l'antífrasi mostra que els trobava a faltar."}, {"q": "Què vol dir amb «Encara no he entés quin valor tenia abans, però és evident que ara en té un altre»?", "o": ["Es burla de l'expressió buida del projecte i suggerix que la plaça ha perdut valor", "Admira el llenguatge tècnic dels arquitectes", "Reconeix que no entén d'urbanisme i renuncia a opinar"], "e": "Juga amb «posa en valor»: la plaça té «un altre» valor, és a dir, pitjor."}, {"q": "Quina funció té l'afegit «Potser exagere, però no gaire» després de l'anècdota de l'ou?", "o": ["Reconeix la hipèrbole, però insistix que la calor és realment extrema", "Retira la crítica i demana disculpes", "Indica que el turista li va contar una mentida"], "e": "Admet l'exageració per a reafirmar, irònicament, el fons de la queixa."}, {"q": "Què vol dir realment amb «Ningú no podrà dir que l'Ajuntament no fa res per l'envelliment actiu»?", "o": ["Que la calor obliga la gent gran a travessar la plaça corrent: la plaça és hostil", "Que l'Ajuntament hi organitza activitats esportives per a majors", "Que valora positivament la política social municipal"], "e": "Presenta com un èxit el fet que els majors hagen de córrer per a no cremar-se."}, {"q": "Per què l'autor atribuïx l'absència dels xiquets als deures o a les pantalles?", "o": ["Fingix buscar altres culpables per a fer més evident que la culpa és de la plaça", "Perquè creu sincerament que les pantalles són el problema", "Perquè els mateixos xiquets li ho han explicat"], "e": "Recorre a tòpics («com tothom sap») per a ridiculitzar les excuses; el lector entén que la causa és la plaça."}, {"q": "Què expressa la frase «Jo, per si de cas, ja m'he comprat un para-sol»?", "o": ["Que no confia que els arbres arriben a fer ombra mentre ell visca", "Que està il·lusionat amb la segona fase de les obres", "Que se'n va de vacances a la platja"], "e": "Calcula que només els nets gaudiran de l'ombra; el para-sol mostra la seua desconfiança en les promeses."}, {"q": "Quina és la intenció de la proposta final del concurs d'ous fregits?", "o": ["Denunciar amb sàtira que la plaça és inhabitable per la calor", "Proposar seriosament una activitat turística", "Demanar que es facen més activitats gastronòmiques a les festes"], "e": "L'«ús per al qual sembla haver sigut concebuda» és fregir ous: la plaça només servix per a acumular calor."}]}, {"passage": {"media": "text", "title": "Relat: El jurat inesperat", "lines": [{"text": "Aquell dissabte de festes només volia una cosa: que algú de l'Ajuntament em segellara la sol·licitud per a corregir el nom del meu gos en el cens d'animals. Ho sé, no sembla un pla emocionant, però el veterinari l'havia registrat com a «Rufo» en compte de «Rufí», i jo soc d'eixes persones que no poden dormir quan saben que un error administratiu els mira des d'un calaix."}, {"text": "Com que l'oficina estava tancada, em van dir que el regidor de Festes era a la plaça de l'Església. Hi vaig anar amb la carpeta davall del braç i la camisa blanca que porte quan he de fer gestions, perquè crec, ingènuament, que la roba neta impressiona els funcionaris. La plaça estava plena de fum, d'olor de llenya de taronger i de quaranta paelles en fila."}, {"text": "—Per fi! —va cridar un home amb un mocador de festes al coll en veure'm—. Vosté és el de València, no? El del restaurant? —Bé —vaig dir, pensant en la gestoria on treballe, que és al carrer de València—, jo vinc pel tema del registre. —Clar, clar, el registre de puntuacions. Seguisca'm."}, {"text": "Abans que poguera explicar-me, ja estava assegut darrere d'una taula amb un mantell de ganxet, entre una senyora que es va presentar com «la presidenta de la comissió» i un home gran que no va dir res en tota la vesprada, però que mastegava amb una autoritat imponent. Em van posar un bolígraf en una mà, una cullera en l'altra i un full amb quatre criteris: «punt de l'arròs», «socarrat», «sabor» i «presentació»."}, {"text": "Vaig intentar aclarir-ho tres vegades. La primera, la presidenta em va interrompre per a dir-me que no fera el modest. La segona, el regidor em va donar uns colpets a l'esquena i va comentar a tothom que «els grans cuiners sempre diuen que no en saben». La tercera ja no hi vaig posar gaire convicció, perquè m'havien servit la paella número set i, sincerament, el socarrat era extraordinari."}, {"text": "Vaig descobrir que tinc un talent natural per a la crítica gastronòmica. Només cal arrufar el front, deixar la cullera a l'aire uns segons i dir «interessant» amb veu greu. Els concursants em miraven amb una mescla de respecte i terror. Un xic va gosar preguntar-me què pensava de la seua paella amb carxofes, i li vaig respondre que tenia «molta personalitat». Encara no sé què volia dir, però ell se'n va anar emocionat, quasi plorant."}, {"text": "Cap a les sis, quan ja havíem tastat trenta-dues paelles i jo havia deixat de sentir les cames, va aparéixer un senyor amb un davantal impecable i cara de pocs amics. Era el cuiner de València. Venia tard perquè s'havia perdut. Va mirar la meua cadira, va mirar la meua camisa blanca i va mirar el full de puntuacions, on jo havia anotat, al costat de la paella número set: «Una obra d'art. Insistir en el socarrat»."}, {"text": "El regidor es va quedar blanc. La presidenta, en canvi, no va perdre la calma: va declarar que dos jurats valien més que un i va fer seure el cuiner a la meua esquerra. Ell no em va dirigir la paraula en tota la vesprada, però em vaig fixar que copiava les meues puntuacions. Va guanyar la número set. El meu gos, per cert, encara es diu Rufo en el cens, però ara tinc tres invitacions a dinar per a l'any que ve."}]}, "exercises": [{"q": "Com es presenta el narrador quan explica que no pot dormir per un error administratiu?", "o": ["Com una persona meticulosa, i se'n burla amb autoironia", "Com una persona amb un problema greu d'insomni", "Com algú que vol canviar el nom del gos perquè no li agrada"], "e": "L'exageració («un error administratiu els mira des d'un calaix») mostra que es riu de la seua pròpia mania."}, {"q": "En què consistix l'equívoc que desencadena la història?", "o": ["«El de València» i «el registre» signifiquen coses diferents per a cada interlocutor", "El narrador es fa passar pel cuiner per a poder menjar de franc", "El regidor l'havia convidat a ser jurat setmanes abans"], "e": "L'home pensa en el cuiner i en el registre de puntuacions; el narrador, en el carrer de la gestoria i en el registre del cens."}, {"q": "Com interpreta el regidor les protestes del narrador?", "o": ["Com una prova de modèstia que confirma que és el cuiner", "Com un senyal que s'ha equivocat de persona", "Com una falta de respecte cap als concursants"], "e": "«Els grans cuiners sempre diuen que no en saben»: com més ho nega, més se'l creuen."}, {"q": "Per què el narrador deixa d'insistir a la tercera vegada?", "o": ["Perquè la paella li agradava i ja no tenia gaire interés a desfer l'equívoc", "Perquè el van amenaçar si no feia de jurat", "Perquè va entendre que de debò l'havien nomenat jurat"], "e": "«Ja no hi vaig posar gaire convicció, perquè […] el socarrat era extraordinari»: insinua que li convenia callar."}, {"q": "Què ironitza el narrador quan parla del seu «talent natural per a la crítica gastronòmica»?", "o": ["La crítica pretensiosa, que es basa en gestos i paraules buides", "La seua llarga experiència com a cuiner", "La falta d'educació dels concursants"], "e": "Només cal «arrufar el front» i dir «interessant»; ni ell mateix sap què volia dir «molta personalitat»."}, {"q": "Què suggerix que el cuiner copiara les puntuacions del narrador?", "o": ["Que, malgrat la seua actitud distant, donava per bo el criteri del narrador", "Que el narrador li feia trampes per a guanyar", "Que el cuiner no sabia omplir el full de puntuacions"], "e": "No li parla, però adopta les seues notes: és un reconeixement tàcit i còmic."}, {"q": "Com resol la presidenta la situació quan es descobrix l'error?", "o": ["Amb pragmatisme: l'integra en el jurat sense admetre l'equivocació", "Expulsant el narrador de la taula del jurat", "Anul·lant el concurs i repetint les votacions"], "e": "«Va declarar que dos jurats valien més que un»: salva les aparences sense reconéixer l'error."}, {"q": "Quina ironia hi ha en el final del relat?", "o": ["No aconseguix el que buscava, però obté un reconeixement que no buscava", "El gos acaba guanyant el concurs de paelles", "El narrador perd la faena per haver mentit"], "e": "El nom del gos continua mal escrit, però té «tres invitacions a dinar per a l'any que ve»."}]}]},
  {"id": "6bd06f54-2d21-5502-bb79-972590925f4d", "category": "expressio_escrita", "type": "c1_ee_narracio", "sort_order": 1, "title": "Narrar, descriure i explicar", "name": "Relats, cròniques i textos descriptius", "content": "Escriu textos explicatius, descriptius i narratius sobre fets reals o imaginaris, clars i detallats, amb un estil personal adequat al lector, que integren diversos subtemes i acaben amb una conclusió apropiada.", "icon": "✍️", "color": "#E1BEE7", "exercises": [{"q": "La revista literària de la teua universitat convoca un concurs de relats breus amb el lema «El dia que tot va canviar». Escriu un relat, basat en fets reals o imaginaris, en què una decisió aparentment insignificant (agafar un tren diferent, contestar una telefonada, entrar en una botiga per a protegir-se de la pluja...) acaba transformant la vida del protagonista. Presenta una situació inicial ben descrita, desenvolupa el conflicte combinant narració, descripció i algun fragment de diàleg, i tanca'l amb un desenllaç que done sentit al conjunt. Cuida l'estil: varietat de temps verbals, riquesa lèxica i un to personal que capte l'interés del lector des de la primera línia.", "w": {"min_words": 250, "max_words": 300}}, {"q": "Una fundació cultural prepara una publicació digital adreçada a persones procedents d'altres països que acaben d'instal·lar-se a la Comunitat Valenciana. Et demanen un text explicatiu i descriptiu sobre un ofici, una tradició o un espai del teu poble o de la teua comarca que estiga en perill de desaparéixer (un ofici artesà, un mercat setmanal, una festa, una construcció tradicional...). Descriu-lo amb detall, explica'n l'origen i la funció que tenia, integra-hi la manera com l'han viscut diverses generacions i les causes del seu declivi, i acaba amb una conclusió sobre què es perdria si desapareguera. Tin en compte que els lectors no coneixen la realitat local: explica les referències que no siguen evidents.", "w": {"min_words": 250, "max_words": 300}}, {"q": "El butlletí d'antics alumnes del teu institut publica una secció titulada «Vint anys després», en què exalumnes recorden un episodi de la seua època d'estudiants. Escriu una crònica d'un viatge d'estudis, d'una excursió o d'una activitat escolar en què les coses no van eixir com estava previst. Narra els fets en ordre, descriu els llocs i les persones principals, combina el to humorístic amb algun moment de reflexió i acaba explicant què en vas aprendre o com ho veus ara, amb la perspectiva del temps.", "w": {"min_words": 220, "max_words": 260}}]},
  {"id": "73a232ed-45df-51e6-9555-66e931942939", "category": "expressio_escrita", "type": "c1_ee_correspondencia", "sort_order": 2, "title": "Correspondència personal", "name": "Emocions, humor i ironia", "content": "Escriu cartes i correus personals i semiformals amb claredat, precisió i flexibilitat, expressant diferents graus d'emoció i subratllant el que és important per mitjà de l'al·lusió, l'humor o la ironia.", "icon": "💌", "color": "#F8BBD0", "exercises": [{"q": "Fa dos anys que no parles amb Jordi, un amic de la infància, perquè una discussió sobre un negoci que compartíeu va acabar malament. Ara t'has assabentat per terceres persones que ha passat una malaltia greu i que ja s'ha recuperat. Escriu-li una carta personal: explica-li com t'has assabentat de la notícia i què has sentit, reconeix la teua part de responsabilitat en la discussió sense justificar-te en excés, evoca algun episodi compartit que tinga un valor especial per als dos (pots fer-hi alguna al·lusió que només ell entendrà) i proposa-li tornar a veure-vos. Gradua l'emoció: ha de ser una carta sincera, però no melodramàtica.", "w": {"min_words": 250, "max_words": 300}}, {"q": "La teua amiga Laia t'escriu eufòrica: després de quatre intents, ha aprovat les oposicions de mestra i li han donat destinació en un poble de muntanya on no ha estat mai. Tu, en canvi, acabes de passar una setmana catastròfica: t'han entrat a robar al cotxe, se t'ha espatlat l'ordinador just abans d'una entrega important i el gat del veí ha decidit instal·lar-se en el teu balcó. Contesta-li amb un correu en què la felicites amb tot l'entusiasme que mereix i subratlles el valor de la seua constància, li fas alguna broma afectuosa sobre la nova vida a la muntanya i li contes les teues desgràcies amb humor i ironia, relativitzant-les.", "w": {"min_words": 220, "max_words": 260}}, {"q": "Fa tres mesos que el pati de la teua comunitat de veïns està en obres, que en principi havien de durar tres setmanes, i l'empresa encara no ha donat cap explicació. Escriu un correu semiformal a l'administradora de la finca, a qui coneixes de fa anys i amb qui tens una relació cordial: fes-li saber el malestar dels veïns, subratlla els problemes concrets que causa la situació amb una ironia fina que no resulte ofensiva i demana-li que faça de mitjancera amb l'empresa per a obtindre un calendari definitiu. Cuida l'equilibri entre la cordialitat i la fermesa.", "w": {"min_words": 180, "max_words": 220}}]},
  {"id": "74720aa0-0b64-5eac-8378-fa4e019b3909", "category": "expressio_escrita", "type": "c1_ee_argumentacio", "sort_order": 3, "title": "Argumentar en àmbits diversos", "name": "Privat, laboral i acadèmic", "content": "Escriu argumentacions en els àmbits privat, laboral i acadèmic que subratllen les idees principals i defenen el teu punt de vista de manera elaborada, amb idees complementàries, justificacions i exemples pertinents fins a arribar a una conclusió apropiada.", "icon": "⚖️", "color": "#FFE0B2", "exercises": [{"q": "El teu pare, de huitanta-dos anys, viu sol en un poble de l'interior des que va morir la teua mare i comença a tindre problemes de mobilitat. Els teus germans proposen que vaja a viure a una residència de la capital de comarca; tu creus que hi ha alternatives millors (ajuda a domicili, teleassistència, que passe temporades a casa de cada fill...) o bé, al contrari, que la residència és la millor opció però per motius diferents dels que ells donen. Escriu un correu llarg als teus germans en què exposes el teu punt de vista de manera elaborada: reconeix els arguments que ells han plantejat, defén la teua postura amb raons complementàries i exemples concrets, anticipa les objeccions que et poden fer i acaba amb una proposta per a prendre la decisió en comú. És un tema delicat: el to ha de ser afectuós, però l'argumentació ha de ser sòlida.", "w": {"min_words": 250, "max_words": 300}}, {"q": "Treballes en una cooperativa agroalimentària de la Ribera Alta que té cent vint treballadors. La direcció vol retallar el pressupost de formació interna per a compensar l'augment dels costos energètics. Com a membre del comité d'empresa, redacta un escrit adreçat al consell rector en què defenses que cal mantindre, o fins i tot ampliar, la inversió en formació. Formula la idea principal des del començament, desenvolupa almenys tres arguments (productivitat, seguretat laboral, retenció del talent, adaptació tecnològica...) amb justificacions i exemples pertinents, rebat el criteri estrictament comptable de la direcció i conclou amb una proposta viable. Usa un registre formal i els mecanismes de cohesió propis dels textos argumentatius.", "w": {"min_words": 250, "max_words": 300}}, {"q": "En l'assignatura d'Ètica i Societat de primer curs de grau us han demanat un assaig breu sobre esta qüestió: «Haurien d'exigir les universitats un període de voluntariat o de servici comunitari per a obtindre qualsevol títol de grau?». Escriu l'assaig: planteja la qüestió i la seua rellevància, defén una tesi clara, desenvolupa-la amb arguments jerarquitzats, idees complementàries i exemples, discutix almenys una posició contrària de manera rigorosa i arriba a una conclusió que no es limite a repetir el que ja has dit. Usa un registre acadèmic, construccions impersonals quan convinga i connectors variats.", "w": {"min_words": 250, "max_words": 300}}, {"q": "Un diari digital ha publicat una columna titulada «Els museus sobren», en què l'autor sosté que, en l'època de les visites virtuals i de les reproduccions en alta resolució, mantindre museus físics és un luxe que les administracions no es poden permetre, i que eixos diners s'haurien de destinar a digitalitzar el patrimoni. Escriu una rèplica per a publicar-la en el mateix mitjà: resumix amb fidelitat la tesi de l'autor, reconeix el que hi pot haver de raonable, rebat-ne els arguments principals amb contraarguments ben justificats i exemples, i amplia el debat amb alguna idea complementària que ell no haja considerat. Acaba amb una conclusió contundent. Pots recórrer a la ironia, però sense desqualificacions personals.", "w": {"min_words": 220, "max_words": 260}}]},
  {"id": "9faadc5e-61ef-5111-b962-c2e5ef2834e8", "category": "expressio_escrita", "type": "c1_ee_resum", "sort_order": 4, "title": "Resumir i sintetitzar", "name": "Destriar l'essencial de l'accessori", "content": "Resumix textos extensos destriant-ne la informació bàsica de l'accessòria, sintetitzant-ne les idees i modificant-ne l'estructura quan convé.", "icon": "📋", "color": "#FFF9C4", "blocks": [{"passage": {"media": "text", "title": "L'oblit, eixe aliat desconegut", "lines": [{"text": "Durant segles, l'oblit ha tingut mala fama. El consideràvem un defecte, una avaria del cervell que ens fa perdre claus, noms i aniversaris, i que amb l'edat s'agreuja fins a convertir-se en motiu d'angoixa. Tanmateix, en les últimes dècades la neurociència ha començat a mirar-lo amb uns altres ulls. Lluny de ser una simple fallada, oblidar seria una funció activa i necessària, tan important per a la ment com recordar."}, {"text": "Per a entendre-ho, convé tindre present com es formen els records. Cada experiència deixa una empremta en forma de connexions entre neurones. Si eixes connexions es reactiven, perquè hi tornem a pensar, perquè la informació ens resulta útil o perquè va associada a una emoció intensa, s'enfortixen i el record es consolida. Si no, es debiliten progressivament. Fins ací, res de nou: és el que ja intuïa qualsevol estudiant que repassava la lliçó la nit abans de l'examen. La novetat és que el cervell no es limita a deixar que els records poc usats s'esvaïsquen per inèrcia, sinó que disposa de mecanismes específics per a esborrar-los o, almenys, per a fer-los inaccessibles."}, {"text": "Per què hauria de fer-ho? La resposta més acceptada és que un cervell que ho retinguera tot seria un cervell col·lapsat. Imaginem que recordàrem amb el mateix detall cada una de les vegades que hem aparcat el cotxe: quan intentàrem saber on l'hem deixat hui, ens assaltarien centenars d'imatges semblants i no seríem capaços de destriar la bona. Oblidar els detalls irrellevants permet, per tant, quedar-se amb l'essencial i generalitzar: no recordem cada gos que hem vist en la vida, però en reconeixem un de seguida."}, {"text": "Els casos excepcionals ho confirmen. La literatura científica ha descrit persones amb una memòria autobiogràfica extraordinària, capaces de dir què van menjar un dimarts qualsevol de fa quinze anys. Lluny de viure-ho com un privilegi, moltes afirmen que el passat les persegueix i que els costa deixar arrere els moments dolorosos. La ficció ja ho havia anticipat: Funes, el personatge de Borges que no podia oblidar res, ho recordava tot, però era incapaç de pensar, perquè pensar és oblidar diferències, és abstraure."}, {"text": "L'oblit té també una dimensió emocional. Hi ha investigacions que suggerixen que, mentre dormim, el cervell no sols consolida el que hem aprés, sinó que rebaixa la càrrega emocional dels records: aquell episodi humiliant de fa uns anys continua ahí, però ja no fa mal com el primer dia. Quan este procés falla, com sembla que passa en alguns trastorns d'ansietat o d'estrés posttraumàtic, el record conserva intacta la capacitat de fer patir."}, {"text": "Res d'això no vol dir que tot oblit siga saludable. Les malalties neurodegeneratives, com l'Alzheimer, destruïxen de manera indiscriminada records valuosos i, a la llarga, la identitat mateixa de qui les patix. La diferència és clara: l'oblit sa és selectiu i té una funció; el patològic és indiscriminat i no respon a cap lògica."}, {"text": "Potser, doncs, hauríem de reconciliar-nos amb els nostres oblits quotidians. No recordar on hem deixat les ulleres no és necessàriament un senyal d'alarma, sinó, moltes vegades, el preu raonable que paguem per tindre una ment àgil, capaç de distingir el que importa del que no importa. Com repetia una vella professora de qui firma estes línies, la memòria no és un magatzem, sinó un jardí: cal podar-la perquè hi creixca alguna cosa."}]}, "exercises": [{"q": "Llig l'article de divulgació i escriu-ne un resum per a la revista digital d'un institut, adreçat a alumnat de batxillerat. Destria la informació bàsica de l'accessòria: no hi han d'aparéixer les anècdotes ni els exemples que només il·lustren una idea, sinó la tesi i els arguments que la sostenen. No seguisques necessàriament l'ordre de l'original: comença per la tesi central, agrupa les funcions de l'oblit (cognitiva i emocional) i acaba amb la distinció entre oblit sa i patològic. Reformula les idees amb les teues paraules, sense copiar frases senceres i sense afegir-hi opinions personals.", "w": {"min_words": 180, "max_words": 220}}]}, {"passage": {"media": "text", "title": "Les llavors que tornen", "lines": [{"text": "A principis de segle, quan Remei Gisbert va heretar l'hort del seu avi, va trobar en una calaixera del magatzem una vintena de pots de vidre amb etiquetes escrites a mà: «tomaca de penjar», «bajoca del ganxet», «meló d'Alger negre»... Eren llavors que la família havia guardat any rere any durant generacions. Aquell descobriment, que per a molta gent haguera sigut una simple curiositat, va ser per a ella el començament d'un projecte que hui implica més de dues-centes persones de tres comarques."}, {"text": "El problema de fons és ben conegut. Al llarg del segle XX, la modernització agrària va substituir les varietats locals per unes poques varietats comercials, més productives i uniformes, pensades per a resistir el transport i per a madurar totes alhora. Les varietats tradicionals, adaptades durant segles al clima i als sòls de cada contrada, van anar desapareixent dels camps i, amb elles, els coneixements dels qui les cultivaven. Quan mor un llaurador que guardava una llavor única, no sols es perd una planta: es perd també la manera de sembrar-la, de cuinar-la i de conservar-la."}, {"text": "Per a frenar eixa pèrdua van nàixer els bancs de llavors comunitaris. A diferència dels grans bancs de germoplasma, que conserven les mostres en cambres frigorífiques, els comunitaris funcionen amb una lògica senzilla: qui s'emporta llavors es compromet a sembrar-les i a tornar-ne, al final de la temporada, una quantitat igual o superior. La conservació, per tant, es fa en el camp, on les plantes continuen adaptant-se a unes condicions que canvien."}, {"text": "L'associació que va impulsar Gisbert, Llavors de la Vall, va començar amb els pots de l'avi i una taula plegable en el mercat dels dissabtes. Hui té catalogades més de tres-centes varietats, organitza intercanvis dos vegades l'any i fa tallers en les escoles. «Al principi venien sobretot persones majors que buscaven la tomaca que menjaven de xicotetes», explica. «Ara també vénen molts jóvens que han tornat al poble i volen cultivar d'una altra manera.»"}, {"text": "Els defensors d'estes iniciatives hi veuen avantatges que van més enllà de la nostàlgia. Les varietats locals solen necessitar menys aigua i menys tractaments, perquè estan adaptades a l'entorn, i la diversitat genètica que conserven pot ser decisiva davant del canvi climàtic, ja que entre elles poden trobar-se plantes més resistents a la sequera o a plagues noves. També hi ha un argument gastronòmic: diversos restaurants de la zona han començat a incloure en les cartes productes d'estes varietats, cosa que n'ha fet augmentar la demanda."}, {"text": "No tot són flors, però. Els rendiments són sovint més baixos, la producció és irregular i la normativa sobre la comercialització de llavors, pensada per a les varietats registrades, dificulta que els agricultors professionals les puguen vendre. Per això, de moment, la majoria de les varietats recuperades es cultiven en horts familiars i en xicotetes explotacions que venen directament al consumidor."}, {"text": "Gisbert no s'enganya: sap que uns quants pots de vidre no canviaran el model agrari. Però està convençuda que cada llavor que torna a la terra és una porta que es manté oberta. «No sabem què necessitarem d'ací a cinquanta anys», diu. «Si deixem que estes varietats desapareguen, ens tanquem unes possibilitats que ni tan sols coneixem.»"}]}, "exercises": [{"q": "Formes part d'un grup de treball que prepara un dossier sobre agricultura sostenible per a la regidoria de medi ambient del teu municipi. Resumix el reportatge per a incloure'l en el dossier. Com que els lectors són tècnics municipals, has de prescindir dels elements narratius i anecdòtics (la història personal, les citacions literals) i reorganitzar la informació en quatre parts: el problema que es planteja, la solució que proposen els bancs de llavors comunitaris i com funcionen, els avantatges que se'ls atribuïxen i les limitacions que tenen. Usa un registre formal i objectiu i connectors que facen explícita l'estructura.", "w": {"min_words": 180, "max_words": 220}}]}]},
  {"id": "54aad8bf-be91-5d16-b5a2-4c4ef1c948d4", "category": "expressio_escrita", "type": "c1_ee_apunts", "sort_order": 5, "title": "Apunts de conferències", "name": "Notes fidels per a altres", "content": "Pren apunts detallats d'una conferència i transcriu-los d'una manera tan precisa i fidel a l'original que en puguen fer ús altres persones.", "icon": "📝", "color": "#DCEDC8", "blocks": [{"passage": {"media": "audio", "title": "Conferència: els noms de lloc, memòria del territori", "lines": [{"speaker": "Ponent", "voice": "lluc", "text": "Bona vesprada. Moltes gràcies a l'organització d'estes jornades per haver-me convidat. El tema que vull tractar hui és la toponímia, és a dir, l'estudi dels noms de lloc, i la tesi que vull defendre és senzilla: els noms de lloc són un arxiu, probablement el més antic que tenim, de la història d'un territori. La desenvoluparé en tres apartats: primer, quins tipus de topònims hi ha; segon, què ens diuen de les cultures que ens han precedit; i tercer, per què estan amenaçats i què podem fer per a conservar-los."}, {"speaker": "Ponent", "voice": "lluc", "text": "Comencem per la classificació. Solem distingir entre la macrotoponímia, que són els noms de pobles, rius i serres, és a dir, els que trobem en qualsevol mapa, i la microtoponímia, que són els noms de partides, fonts, barrancs, camins o masos, coneguts sovint només per la gent del lloc. Els primers són relativament pocs i molt estables; els segons, en canvi, es compten per centenars en cada terme municipal i són molt més fràgils. Retingueu esta distinció, perquè hi tornaré al final."}, {"speaker": "Ponent", "voice": "lluc", "text": "Segon apartat: què ens conten els noms. Els topònims funcionen com els estrats d'un jaciment arqueològic. En una mateixa comarca podem trobar noms d'origen preromà, que sovint ja no sabem interpretar; noms d'origen llatí, com els que contenen paraules com pont, vila o font; i una capa àrab molt rica, que es reconeix en els noms que comencen per Beni-, que vol dir 'fills de' i fa referència a un llinatge, o per Al-, que correspon a l'article àrab, com en Alcalà, que significa 'el castell'. Damunt d'estes capes hi ha els noms posteriors a la conquesta cristiana, molts dels quals descriuen el paisatge: la Coma, el Pla, la Rambla, les Fontanelles. Un mapa de topònims és, per tant, el mapa d'una successió de cultures. Però hi ha més: la microtoponímia ens informa de cultius desapareguts, com en una partida que es diga els Morerars, on segurament es criaven cucs de seda; d'oficis oblidats, com en el Forn de Calç; o de fenòmens naturals, com en el Barranc de les Avingudes."}, {"speaker": "Ponent", "voice": "lluc", "text": "I ara, el tercer apartat: l'amenaça. La microtoponímia s'ha transmés oralment durant segles, però l'abandó del camp ha trencat esta cadena. Quan una terra deixa de treballar-se, els noms de les partides deixen de pronunciar-se, i quan moren les persones que els coneixien, desapareixen per sempre. A més, la cartografia oficial ha introduït de vegades formes deformades o traduïdes que han acabat substituint les autèntiques."}, {"speaker": "Ponent", "voice": "lluc", "text": "Què podem fer? Proposaré tres línies d'actuació. Primera: fer reculls sistemàtics, entrevistant les persones majors amb un mapa al davant i enregistrant-ne la pronúncia. Segona: incorporar els noms recollits, amb la forma correcta, a la cartografia i a la senyalització dels camins. I tercera: implicar-hi les escoles, perquè l'alumnat investigue els noms del seu terme i els faça seus. Un topònim que es fa servir és un topònim que viu. En definitiva, conservar els noms de lloc no és un caprici d'erudits: és conservar la memòria del territori. Moltes gràcies."}]}, "exercises": [{"q": "Estudies un màster de patrimoni cultural i assistixes a esta conferència. Una companya del màster no hi ha pogut anar i necessita la informació per a un treball. Escolta la conferència i pren apunts detallats. Després, transcriu-los en un text ordenat i ben cohesionat adreçat a ella, tan precís i fidel a l'original que el puga utilitzar com a font: recull la tesi del ponent, la classificació dels topònims, les capes històriques amb els exemples que s'hi donen, les causes de l'amenaça i les tres propostes d'actuació. Respecta l'estructura de la conferència, distingix clarament el que diu el ponent i no hi afegisques opinions teues.", "w": {"min_words": 250, "max_words": 300}}]}, {"passage": {"media": "audio", "title": "Conferència: la roba que llancem", "lines": [{"speaker": "Ponent", "voice": "gina", "text": "Bon dia a tothom. En esta sessió parlaré del cicle de vida de la roba i, en concret, d'un problema que fins fa poc ha passat desapercebut: els residus tèxtils. L'exposició s'organitza en quatre punts: com ha canviat el consum de roba, què passa amb la roba que llancem, quins obstacles dificulten el reciclatge i quines estratègies semblen més prometedores."}, {"speaker": "Ponent", "voice": "gina", "text": "Primer punt: el consum. En les últimes dècades, el model conegut com a moda ràpida ha multiplicat el nombre de col·leccions que les marques trauen cada any i ha abaratit els preus fins a extrems inèdits. El resultat és que comprem molta més roba que fa trenta anys i que la portem moltes menys vegades abans de desfer-nos-en. De fet, moltes peces es dissenyen per a durar una sola temporada, i les rebaixes, que abans eren puntuals, ara són pràcticament permanents."}, {"speaker": "Ponent", "voice": "gina", "text": "Segon punt: el destí de la roba que llancem. Hi ha la creença que la roba que depositem en els contenidors de recollida acaba vestint algú que la necessita. Només és cert en part. Una fracció xicoteta, la de més qualitat, es reutilitza en botigues de segona mà del mateix país. Una part important s'exporta a altres continents, on sovint satura els mercats locals i acaba en abocadors a l'aire lliure. I una altra part, la més deteriorada, s'incinera o s'enterra. Només un percentatge molt reduït es convertix en fibra nova."}, {"speaker": "Ponent", "voice": "gina", "text": "Tercer punt: per què costa tant reciclar la roba. Hi ha tres obstacles principals. El primer són les mescles de fibres: una samarreta que combina cotó i polièster és molt difícil de separar en els seus components. El segon són els elements afegits, com botons, cremalleres o estampats, que cal retirar abans de processar el teixit. I el tercer és econòmic: amb els preus actuals, produir fibra nova sovint resulta més barat que recuperar-la."}, {"speaker": "Ponent", "voice": "gina", "text": "Quart i últim punt: les estratègies. Les resumiré en tres. La primera actua abans de la producció: és l'ecodisseny, que consistix a dissenyar peces d'una sola fibra, fàcils de desmuntar i pensades per a durar. La segona és la responsabilitat ampliada del productor, és a dir, que les marques paguen la gestió dels residus que generen, de manera que els isca més a compte fabricar roba duradora. I la tercera depén de nosaltres: comprar menys, reparar més i allargar la vida de cada peça. Recordeu que la peça més sostenible és la que ja tenim en l'armari. Moltes gràcies per la vostra atenció."}]}, "exercises": [{"q": "Treballes en una cooperativa de consum responsable i has assistit a esta conferència. Un company de l'equip que prepara una campanya de sensibilització sobre la moda no hi va poder anar. Escolta la conferència i pren apunts detallats. Després, transcriu-los en un text ordenat i complet adreçat a ell, de manera que puga treballar a partir de la informació sense haver escoltat el ponent: respecta l'estructura en quatre punts, recull amb precisió els tres destins de la roba llançada, els tres obstacles del reciclatge i les tres estratègies proposades, i deixa clar quines idees remarca la ponent com a més importants.", "w": {"min_words": 250, "max_words": 300}}]}]},
  {"id": "a237b2af-1aff-5b68-b1f1-779ddfa37e8c", "category": "expressio_escrita", "type": "c1_ee_reelaboracio", "sort_order": 6, "title": "Reelaborar textos", "name": "Nous lectors, noves funcions", "content": "Elabora textos nous, adequats, coherents i cohesionats a partir de textos de referència, i adapta'ls a lectors, funcions comunicatives i contextos diferents.", "icon": "🔄", "color": "#B2EBF2", "blocks": [{"passage": {"media": "text", "title": "Informe tècnic sobre l'arbratge del passeig de la Mar", "lines": [{"text": "Ajuntament de Benissalt. Àrea de Medi Ambient, Parcs i Jardins. Informe tècnic núm. 37/2026. Assumpte: avaluació de l'estat fitosanitari i estructural dels plàtans d'ombra del passeig de la Mar."}, {"text": "1. Antecedents. Arran de la caiguda d'una branca de grans dimensions el 3 de març, que va danyar dos vehicles estacionats sense causar danys personals, la Regidoria de Medi Ambient va encarregar a este servici una inspecció de la totalitat dels exemplars del passeig, un total de 64 arbres plantats, segons els arxius municipals, entre 1958 i 1962."}, {"text": "2. Metodologia. S'ha aplicat el mètode d'avaluació visual de l'arbre, complementat amb proves de resistència mitjançant tomògraf sònic en els exemplars que presentaven símptomes externs de degradació. S'han valorat l'estat del sistema radicular, del tronc i de la capçada, així com la presència de fongs de podridura i de plagues."}, {"text": "3. Resultats. a) 41 exemplars (64 %) presenten un estat bo o acceptable i només requerixen manteniment ordinari. b) 15 exemplars (23 %) presenten defectes moderats (cavitats parcials, branques amb unions dèbils o compactació del sòl en la zona radicular) que poden corregir-se mitjançant podes de reducció, sistemes d'ancoratge entre branques i descompactació del terreny. c) 8 exemplars (13 %) presenten podridura avançada en la base del tronc, amb una pèrdua de secció resistent superior al 40 %, motiu pel qual se'n considera el risc de fractura alt i no corregible."}, {"text": "4. Valoració. La pavimentació del passeig en la reforma de 1994, que va reduir els escocells a una superfície d'un metre quadrat, i les podes dràstiques practicades fins a l'any 2010 es consideren les causes principals del deteriorament observat. Cal fer constar que el conjunt té un valor paisatgístic i patrimonial notable i que proporciona ombra en una zona de gran afluència durant els mesos d'estiu."}, {"text": "5. Recomanacions. Primera: talar els 8 exemplars de risc alt en el termini màxim d'un mes i substituir-los per exemplars de la mateixa espècie i de calibre gran, a fi de mantindre l'homogeneïtat del passeig. Segona: executar, abans de l'estiu, les actuacions correctores en els 15 exemplars amb defectes moderats. Tercera: ampliar els escocells fins a un mínim de quatre metres quadrats i substituir el paviment circumdant per un de permeable. Quarta: establir un programa de revisió periòdica cada dos anys. Mentre no s'executen les talades, es recomana abalisar la zona d'influència dels exemplars de risc alt i prohibir-hi l'estacionament de vehicles."}, {"text": "Benissalt, 20 de març de 2026. L'enginyera tècnica forestal municipal, Clara Montaner i Puig."}]}, "exercises": [{"q": "Uns dies després d'este informe, els veïns de Benissalt han vist arbres del passeig marcats amb pintura i ha corregut el rumor que l'Ajuntament els tallarà tots. Com a responsable de comunicació de l'Ajuntament, redacta a partir de l'informe un article per al butlletí municipal adreçat a la ciutadania. Dona-li un títol atractiu, desmentix el rumor amb dades clares, explica per què cal talar alguns arbres i què es farà amb els altres, i informa de com afectaran les actuacions els veïns. Canvia el registre tècnic per un de divulgatiu i proper, explica o substituïx els tecnicismes, selecciona la informació que interessa al lector i reorganitza-la segons esta prioritat.", "w": {"min_words": 220, "max_words": 260}}]}, {"passage": {"media": "text", "title": "Ordenança dels horts urbans de Vilanova del Riu", "lines": [{"text": "Ordenança reguladora dels horts urbans municipals de Vilanova del Riu (extracte)."}, {"text": "Article 1. Objecte. Esta ordenança regula l'adjudicació, l'ús i el gaudi de les parcel·les dels horts urbans municipals situats en la partida del Molí Vell, destinades al conreu d'hortalisses, flors i plantes aromàtiques per a l'autoconsum."}, {"text": "Article 2. Persones beneficiàries. Poden optar a una parcel·la les persones majors d'edat empadronades en el municipi amb una antiguitat mínima d'un any que no siguen titulars de cap altra finca rústica. Es reservarà el 20 % de les parcel·les per a persones majors de 65 anys i el 10 % per a entitats sense ànim de lucre i centres educatius."}, {"text": "Article 3. Adjudicació i durada. Les parcel·les s'adjudicaran per sorteig públic entre les sol·licituds admeses. L'adjudicació tindrà una durada de dos anys, prorrogable un any més si la persona adjudicatària ha complit les obligacions establides en esta ordenança. Finalitzat el període, no es podrà presentar una nova sol·licitud fins que haja transcorregut un any."}, {"text": "Article 4. Obligacions. Les persones adjudicatàries estan obligades a: a) cultivar la parcel·la de manera continuada; es considerarà abandonament la falta de conreu durant més de dos mesos sense causa justificada; b) utilitzar exclusivament mètodes de cultiu ecològic, per la qual cosa queda prohibit l'ús de fertilitzants i plaguicides de síntesi química; c) fer un ús responsable de l'aigua de reg, d'acord amb els torns establits per la comissió de seguiment; d) mantindre nets els camins i les zones comunes, i depositar les restes vegetals en el compostador col·lectiu; e) retornar la parcel·la, en finalitzar l'adjudicació, en les mateixes condicions en què es va rebre."}, {"text": "Article 5. Prohibicions. Queda prohibit: a) vendre o comercialitzar els productes obtinguts; b) cedir, llogar o traspassar la parcel·la a terceres persones; c) instal·lar-hi construccions, tanques o elements fixos no autoritzats; d) tindre-hi animals; e) fer foc o cremar restes vegetals."}, {"text": "Article 6. Règim sancionador. L'incompliment de les obligacions o de les prohibicions establides en esta ordenança podrà comportar, previ expedient amb audiència de la persona interessada, la revocació de l'adjudicació, sense perjuí de les sancions econòmiques previstes en la normativa municipal aplicable."}, {"text": "Article 7. Horari. El recinte romandrà obert de 8 a 21 hores de l'1 d'abril al 30 de setembre, i de 8 a 19 hores la resta de l'any."}]}, "exercises": [{"q": "L'institut de Vilanova del Riu ha obtingut una de les parcel·les reservades als centres educatius, i un grup d'alumnes de tercer d'ESO s'encarregarà de cultivar-la. Com a professor o professora responsable del projecte, elabora a partir de l'ordenança una guia de benvinguda per a l'alumnat. Selecciona només les normes que els afecten (no cal parlar del procés d'adjudicació a particulars), transforma el llenguatge jurídic en un text clar, proper i motivador, explica el perquè de les normes més importants amb exemples concrets del dia a dia a l'hort i acaba amb un missatge que els anime a implicar-s'hi. Pots organitzar el text amb subtítols.", "w": {"min_words": 220, "max_words": 260}}]}]},
  {"id": "31de9fd5-c66c-58de-ae45-562a7a9e0964", "category": "expressio_oral", "type": "c1_eo_exposicio", "sort_order": 1, "title": "Exposició de temes complexos", "name": "Ponència en el Fòrum de Pensament amb Remei", "content": "Presenta un tema complex de manera clara i ben estructurada: desenrotlla punts de vista amb justificacions i exemples, integra temes secundaris, arriba a una conclusió apropiada i respon a les preguntes de seguiment.", "icon": "🎙️", "color": "#DCEDC8", "metadata": {"character": "Remei, moderadora d'unes jornades de debat ciutadà", "voice": "gina", "initial_prompt": "Bona vesprada a totes i a tots, i benvinguts a la tercera sessió del Fòrum Mediterrani de Pensament. La persona convidada d'avui ens parlarà d'un tema que ens afecta a tots, encara que no sempre en som conscients. Disposa d'uns deu minuts i, després, obrirem el torn de preguntes. Quan vulga, té la paraula.", "objectius": ["Introduïx el tema, delimita'l i anuncia l'estructura que seguirà la teua exposició.", "Desenrotlla els teus punts de vista amb justificacions, dades i exemples pertinents, i integra-hi els temes secundaris sense perdre el fil.", "Usa connectors i marcadors del discurs formal per a ordenar les idees i fer transicions clares entre les parts.", "Respon a les preguntes de seguiment de la moderadora i del públic ampliant o matisant el que has dit, sense recórrer a respostes evasives.", "Tanca l'exposició amb una conclusió que recupere les idees principals i en derive una reflexió o una proposta."], "prompt": "Ets Remei Climent, periodista cultural i moderadora del Fòrum Mediterrani de Pensament, un cicle de jornades de debat ciutadà que se celebra cada tardor en l'auditori municipal de Sagunt. Tens uns cinquanta-cinc anys, una gran experiència conduint debats, ets cordial però rigorosa i tractes l'aprenent de vosté. L'aprenent és la persona convidada a fer la ponència de la sessió i ha d'exposar un tema complex. Si no en porta cap de pensat, oferix-li'n tres: la gestió de l'aigua en un territori amb sequets cada vegada més llargues; la reducció de la jornada laboral a quatre dies; o l'ús de la intel·ligència artificial en els diagnòstics mèdics. Mentre fa l'exposició, no l'interrompes: limita't a frases breus («Continue, per favor», «Molt interessant») si fa una pausa llarga. Si la intervenció és massa curta o desordenada, demana-li amablement que desenrotlle algun punt concret o que pose un exemple. Quan acabe, fes de moderadora i obri el torn de preguntes. Fes una pregunta per torn i reacciona a cada resposta abans de passar a la següent. Combina preguntes pròpies i preguntes que atribuïxes al públic: un estudiant que demana un exemple pròxim a la vida quotidiana; una regidora que pregunta qui hauria de pagar les mesures que proposa; un senyor escèptic que diu que «tot això són teories d'universitat»; i una pregunta que l'obligue a relacionar el tema amb un altre de secundari (per exemple, les desigualtats territorials, l'educació o el canvi climàtic). Si una resposta és vaga, demana-li que concrete. Fes també de moderadora del temps: si s'estén massa, recorda-li que queda poc temps. Al final, demana-li una conclusió breu, de dos o tres frases, que el públic puga emportar-se'n a casa, agraïx-li la participació i tanca la sessió amb fórmules formals."}},
  {"id": "ee43aa19-8878-5e59-8239-c225ffbdaf5d", "category": "expressio_oral", "type": "c1_eo_instruccions", "sort_order": 2, "title": "Instruccions detallades", "name": "Explicar-li la faena a Pau, que et substituirà", "content": "Dona de manera fiable instruccions detallades sobre un procediment complex, anticipa els problemes que poden sorgir i comprova que l'altra persona ho ha entés tot.", "icon": "🧭", "color": "#B3E5FC", "metadata": {"character": "Pau, el company que et substituirà durant uns mesos", "voice": "lluc", "initial_prompt": "Bon dia! Bé, ací em tens, amb la llibreta preparada. Ja m'han dit que a partir de dilluns em quede jo amb tot el que portes tu, i t'he de confessar que estic un poc nerviós. Per on comencem?", "objectius": ["Explica el procediment de manera ordenada, pas a pas, i deixa clar quines tasques són prioritàries i quines poden esperar.", "Dona instruccions precises: terminis, persones de contacte, documents i eines que cal usar en cada pas.", "Anticipa els problemes i els casos imprevistos i explica com cal actuar en cada un.", "Respon a les preguntes de Pau amb claredat i reformula les explicacions quan no les entenga.", "Comprova que Pau ho ha entés tot, corregix-li els malentesos i resumix al final els punts clau."], "prompt": "Ets Pau Benavent, un company de faena de l'aprenent, de vint-i-nou anys, que el substituirà durant uns mesos perquè l'aprenent se'n va de permís. Ets responsable, atent i amable, però un poc insegur, i et preocupa equivocar-te. Tracta l'aprenent de tu, en un registre col·loquial cuidat. L'aprenent t'ha d'explicar un procediment complex de la seua faena. Si no en té cap de pensat, proposa-li'n un: organitzar la mostra de teatre amateur que fa cada primavera l'Ajuntament d'Alcoi (calendari, companyies, contractes, sales, tècnics, publicitat); gestionar el tancament trimestral de comptes i de l'IVA en una xicoteta empresa de mobles; o coordinar l'arribada i la recepció de grups d'estudiants estrangers en un institut de Castelló. Pren nota en veu alta del que et diu i fes moltes preguntes de detall, una o dues per torn: qui és la persona de contacte, quin és el termini exacte, on es guarda tal document, quina contrasenya o quin programa s'usa, què passa si hi ha un retard. Planteja casos imprevistos perquè haja d'anticipar solucions: el proveïdor no contesta; el sistema informàtic cau el dia que vencen els terminis; el cap demana una cosa que contradiu les instruccions; algú es posa malalt a última hora. Una o dues vegades, entén malament alguna instrucció (per exemple, canvia l'ordre de dos passos o confon dues dates) i repetix-la així, perquè l'aprenent haja de detectar l'error i corregir-te. Si una explicació és massa general («ho fas com sempre», «ja t'apanyaràs»), demana-li que concrete. A la meitat de la conversa, demana-li si pots telefonar-lo durant el permís, perquè haja de deixar clar què has de resoldre tu sol. Al final, intenta resumir el procediment amb les teues paraules, deixant-te algun detall important, i demana-li que el complete; després agraïx-li la paciència i acomiada't."}},
  {"id": "8d5cf9d4-e2e6-5d4d-b45c-cc3728808833", "category": "expressio_oral", "type": "c1_eo_social", "sort_order": 3, "title": "Interacció social", "name": "Sopar de retrobament amb Toni, vint anys després", "content": "Interactua amb flexibilitat en una situació social distesa: comparteix records, fa al·lusions, usa l'humor i la ironia, expressa afecte i improvisa un brindis.", "icon": "🥂", "color": "#F8BBD0", "metadata": {"character": "Toni, antic company de classe de l'aprenent", "voice": "lluc", "initial_prompt": "Però bé, mira qui ha vingut! Vint anys sense vore't i estàs igual... bé, igual no, però quasi! Vine, seu ací al meu costat, que t'he guardat cadira. Ja t'avise que m'han nomenat responsable del brindis i pense passar-te el mort a tu.", "objectius": ["Saluda i reprén la relació amb naturalitat, expressant afecte i alegria pel retrobament.", "Evoca records i anècdotes compartides i fes-hi al·lusions que l'altre puga captar.", "Usa l'humor, la ironia i els jocs de paraules, i reacciona amb agilitat a les bromes de Toni.", "Mostra tacte i empatia quan la conversa toque temes delicats o tristos.", "Improvisa un brindis breu, emotiu i amb un toc d'humor per a tot el grup."], "prompt": "Ets Toni Bellver, de trenta-huit anys, antic company de classe de l'aprenent a l'institut de Llíria. Esteu en el sopar de retrobament de la promoció, vint anys després de la selectivitat, en un restaurant de la serra Calderona. Ets extravertit, bromista i un poc fanfarró, però en el fons molt afectuós; ara treballes de fisioterapeuta i tens dos fills. Parla en registre informal i molt col·loquial, amb expressions com «xe», «vaja tela», «no em digues», «ai, mare». Fes moltes al·lusions a records inventats que l'aprenent ha de seguir i completar: el viatge de fi de curs a Peníscola, quan el professor de física, el senyor Ortells, us va enxampar fent trampes; el grup de música que vau muntar i que només va fer un concert; la nit que es va perdre l'autobús. Usa la ironia i les bromes («Tu sempre tan puntual, eh?», «Ja veig que el gimnàs no és el teu fort») i espera que l'aprenent hi responga amb humor, sense ofendre's. Pregunta-li què ha fet en estos vint anys i reacciona amb interés, admiració fingida o bromes. Fes de narrador de la resta del grup: comenta amb ironia qui ha vingut i qui no («La Sílvia diu que no pot venir perquè té una reunió a Nova York, fixa't tu»). En un moment, posa't seriós i conta una notícia trista (un company, el Joan, va morir fa dos anys, o tu t'has separat fa poc), perquè l'aprenent haja de canviar de to i mostrar tacte. Després recupera l'humor. Cap al final, insistix que l'aprenent faça el brindis davant de tots («Silenci, que parla...!»), escolta'l, reacciona-hi amb entusiasme i proposa quedar més sovint."}},
  {"id": "9321103b-9a53-516f-95a5-a3f6c0cc1a8b", "category": "expressio_oral", "type": "c1_eo_discussio", "sort_order": 4, "title": "Discussions sobre temes abstractes", "name": "Cafè filosòfic amb Clara", "content": "Sosté una discussió animada sobre un tema abstracte i complex, relaciona les seues aportacions amb les de l'altra persona, comprova que l'ha entesa i li demana que aclarisca els punts ambigus.", "icon": "🧠", "color": "#E1BEE7", "metadata": {"character": "Clara, professora de filosofia i dinamitzadora d'un cafè filosòfic", "voice": "gina", "initial_prompt": "Bona vesprada i gràcies per vindre al cafè filosòfic. La pregunta d'avui és d'eixes que no deixen dormir: si un dia una màquina pren millors decisions que nosaltres, encara serem lliures? Jo tinc una intuïció, però abans m'agradaria saber la teua. Per on la prendries, esta pregunta?", "objectius": ["Formula la teua postura amb precisió i desenrotlla-la amb arguments i exemples, encara que el tema siga abstracte.", "Relaciona les teues aportacions amb les de Clara: reprén les seues idees, matisa-les, contrasta-les o construïx a partir d'elles.", "Comprova que has entés bé el que diu Clara reformulant-ho amb les teues paraules.", "Detecta els termes i els raonaments ambigus i demana que s'aclarisquen abans de respondre.", "Mantín la discussió viva amb preguntes i contraexemples, i arriba a una síntesi provisional al final."], "prompt": "Ets Clara Sendra, professora de filosofia de batxillerat a Ontinyent, de quaranta-sis anys, i dinamitzes un cafè filosòfic que es fa un dijous al mes en la biblioteca municipal. Ets curiosa, apassionada i provocadora, t'agraden les paradoxes i els exemples sorprenents. Tracta l'aprenent de tu, en un registre culte però distés. Planteja la qüestió inicial (la llibertat humana davant d'unes màquines que decidixen millor que nosaltres); si l'aprenent prefereix un altre tema, adapta-t'hi: si som la mateixa persona que fa vint anys, si és lícit modificar genèticament els fills, o si té sentit castigar algú per un delicte que encara no ha comés. Discutix amb vivesa: adopta postures fermes, posa contraexemples i experiments mentals (el mòbil que tria per tu la parella ideal, el jutge algorítmic que no s'equivoca mai, el vaixell de Teseu), i qüestiona les afirmacions de l'aprenent. De manera deliberada, introduïx ambigüitats perquè haja de demanar aclariments: usa una paraula clau en dos sentits diferents sense avisar (per exemple, «lliure» com a 'sense coaccions' i com a 'imprevisible'; «natural» com a 'biològic' i com a 'normal'); fes afirmacions vagues com «en cert sentit, ja no decidim res» o «depén de què entenguem per persona»; o usa un pronom ambigu. Si l'aprenent no demana aclariments, continua com si t'haguera entés, però més avant fes evident la confusió perquè se n'adone. Quan l'aprenent reformula el que has dit, confirma-ho o corregix-lo si ho ha interpretat malament. Valora explícitament les connexions que faça amb les teues idees («Això enllaça amb el que deia jo abans...»). No canvies fàcilment d'opinió, però reconeix els bons arguments. Al final, proposa-li construir entre tots dos una síntesi provisional en dues o tres frases i acomiada't citant una pregunta oberta per a la pròxima sessió."}},
  {"id": "4e754f7b-0ca6-5f6c-838b-a9eeea72eda7", "category": "expressio_oral", "type": "c1_eo_entrevistador", "sort_order": 5, "title": "Fer d'entrevistador", "name": "Entrevistar Ferran per a Ràdio Serrella", "content": "Conduïx una entrevista formal com a entrevistador: planteja preguntes preparades, repregunta quan les respostes són evasives, reconduïx la conversa i resumix i valora els punts discutits.", "icon": "📻", "color": "#FFECB3", "metadata": {"character": "Ferran, enginyer agrònom convidat a un programa de ràdio", "voice": "lluc", "initial_prompt": "Bon dia. Ja em diuen els tècnics que estem a punt d'entrar en antena. Vosté és qui em farà l'entrevista, veritat? Molt bé, jo estic preparat. Quan vosté diga, comencem.", "objectius": ["Presenta el programa i el convidat amb fórmules formals i explica als oients el tema de l'entrevista.", "Planteja preguntes ben formulades, ordenades i variades (obertes, concretes, d'opinió) seguint un fil coherent.", "Repregunta quan les respostes siguen evasives, vagues o incompletes, i demana dades o exemples.", "Reconduïx la conversa amb tacte quan el convidat s'allargue o se n'isca del tema, i gestiona el temps.", "Resumix i valora els punts principals que s'han tractat i acomiada el convidat i els oients."], "prompt": "Ets Ferran Martí, enginyer agrònom de cinquanta-dos anys i director de Solcamp, una empresa valenciana inventada que instal·la plaques solars elevades damunt dels camps de conreu (l'anomenada agrovoltaica). Estàs convidat a l'espai d'entrevistes de Ràdio Serrella, una emissora comarcal de l'Alcoià i el Comtat, i l'aprenent fa d'entrevistador. Tracta'l de vosté i parla en un registre formal, però amb el to segur d'una persona acostumada als mitjans. La teua empresa vol instal·lar una planta de quaranta hectàrees en uns camps de cereals i olivets de la comarca: defens que el projecte permet produir energia i continuar conreant, que dona ombra als cultius en uns estius cada vegada més calorosos i que paga als propietaris un lloguer que l'agricultura sola no dona. Però el projecte és polèmic: alguns llauradors i una plataforma veïnal diuen que transformarà el paisatge, que farà pujar el preu de la terra i que els beneficis se'n van fora de la comarca. Deixa que l'aprenent conduïsca l'entrevista: no faces tu les preguntes ni canvies tu de tema. Contesta amb respostes de llargària variable i posa-li-ho difícil perquè haja de gestionar l'entrevista: de vegades fes respostes llarguíssimes i desvia't cap a temes secundaris (la teua infància al camp, les ajudes europees); de vegades sigues evasiu o respon una altra cosa del que t'han preguntat, sobretot quan et pregunten per diners, pels llocs de treball reals que es crearan o per les crítiques de la plataforma veïnal; i usa algun terme tècnic sense explicar-lo (seguidors solars, factor de capacitat) perquè haja de demanar-te que l'aclarisques per als oients. Si l'aprenent repregunta bé, acaba donant una dada concreta o reconeixent algun punt feble. Si no repregunta, no aportes la informació. Si et fa una pregunta incisiva, respon amb un punt de tensió («Em sorprén que vosté es faça ressò d'eixos rumors»), però sense perdre la cortesia. Quan l'aprenent resumisca, corregix-lo amablement si atribuïx alguna cosa que no has dit. Agraïx l'entrevista quan l'acomiade."}},
  {"id": "f04b56af-53fb-51d1-ba8d-a23cf4cdbc68", "category": "expressio_oral", "type": "c1_eo_entrevistat", "sort_order": 6, "title": "Fer d'entrevistat", "name": "Defensar el treball de fi de màster davant d'Amparo", "content": "Respon com a entrevistat en un intercanvi formal exigent, defén el seu treball davant de preguntes difícils i usa l'entonació i la pronunciació per a transmetre matisos com la cortesia, l'èmfasi o la ironia.", "icon": "🎓", "color": "#C5CAE9", "metadata": {"character": "Amparo, presidenta d'un tribunal acadèmic", "voice": "gina", "initial_prompt": "Bon dia. Es constituïx el tribunal per a la defensa pública del treball de fi de màster. Disposa de deu minuts per a presentar-ne els objectius, la metodologia i les conclusions principals. Després, els membres del tribunal li farem les observacions i les preguntes que considerem oportunes. Té la paraula.", "objectius": ["Presenta el treball amb una estructura clara i destaca'n les aportacions principals amb un registre acadèmic formal.", "Respon a les preguntes difícils i a les crítiques amb arguments sòlids, seguretat i cortesia, sense posar-te a la defensiva.", "Reconeix les limitacions del treball quan calga i transforma-les en propostes de millora o línies de futur.", "Usa l'entonació, les pauses i l'èmfasi per a destacar les idees clau i per a transmetre matisos com la cortesia, la ironia suau o la discrepància respectuosa.", "Pronuncia amb claredat i correcció, cuidant les vocals obertes i tancades, les consonants sonores i les síl·labes àtones."], "prompt": "Ets Amparo Gisbert, catedràtica de cinquanta-nou anys i presidenta del tribunal que avalua la defensa pública del treball de fi de màster de l'aprenent en una universitat valenciana. Ets molt exigent, precisa i un poc irònica, però justa; tracta l'aprenent de vosté i usa un registre acadèmic formal. L'aprenent ha de presentar el seu treball; si no en té cap de pensat, proposa-li'n un: l'impacte de les plataformes digitals en la premsa comarcal valenciana; la toponímia menor d'una vall del Maestrat; o l'efecte del soroll urbà en el rendiment escolar en tres col·legis de València. Deixa'l exposar sense interrompre'l, excepte per a demanar-li que vaja acabant si s'allarga molt. Després fes-li preguntes difícils, una per torn, i reacciona a cada resposta: per què la mostra és tan xicoteta i si les conclusions són generalitzables; per què no cita un estudi clau del camp (inventa'n un, d'una investigadora fictícia); si no hi ha una contradicció entre dos capítols; què aporta de nou que no se sabera ja. Fes de veu d'un altre membre del tribunal, el doctor Sanç, més amable, que elogia el treball però planteja un dubte metodològic. Fes algun comentari irònic («Molt valent, per part seua, deixar les conclusions per a l'última pàgina») perquè l'aprenent haja de respondre amb elegància, amb cortesia o amb una ironia suau, sense perdre el respecte. Si respon de manera defensiva o massa insegura, mostra-ho amb un comentari breu. Fixa't també en la manera de dir les coses: si una resposta sona plana o monòtona, demana-li que subratlle amb més claredat quina és, per a ell, l'aportació principal; si pronuncia de manera poc clara algun terme tècnic, demana-li que el repetisca. Al final, demana-li una reflexió breu sobre què milloraria si tornara a començar el treball, comunica-li que el tribunal deliberarà i acomiada't formalment."}}
  ]$data$;
  pautes text := E'\n\n' ||
    'Pautes: l''aprenent prepara el nivell C1 (domini funcional efectiu) de la JQCV i practica l''expressió i interacció orals. Parla en valencià general (normativa de l''AVL), amb el registre que demana la situació (formal quan toca), de manera fluida, espontània i natural, amb un vocabulari ric, precís i idiomàtic: usa connectors variats, estructures complexes, frases fetes i, si la situació ho permet, al·lusions, humor o ironia. ' ||
    'Fes torns breus (màxim 3-4 frases) amb una o dues preguntes per torn. Exigix-li un nivell C1: demana-li que argumente, matise, reformule, done exemples, resumisca o aclarisca; planteja-li objeccions, preguntes inesperades i, de tant en tant, alguna ambigüitat perquè haja de demanar aclariments. Si respon amb frases curtes o estereotipades, repregunta perquè desenvolupe les idees. ' ||
    'Mai no ixes del personatge ni fas lliçons de gramàtica: si l''aprenent s''equivoca o usa un castellanisme, reformula la frase correcta dins de la teua resposta amb naturalitat. ' ||
    E'\nObjectius que ha de complir l''aprenent (guia la conversa perquè els complisca d''un en un, sense enumerar-los): ';
  r jsonb;
  b jsonb;
  e jsonb;
  m jsonb;
  rid uuid;
  pid uuid;
  ppos smallint;
  epos smallint;
BEGIN
  FOR r IN SELECT * FROM jsonb_array_elements(catalog) LOOP
    rid := (r->>'id')::uuid;
    -- Xats: el system_prompt és el del personatge, les pautes del C1 i els objectius.
    m := coalesce(r->'metadata', '{}');
    IF m ? 'prompt' THEN
      m := (m - 'prompt') || jsonb_build_object('system_prompt',
        (m->>'prompt') || pautes ||
        (SELECT string_agg(o, ' | ') FROM jsonb_array_elements_text(m->'objectius') AS o) ||
        ' Quan els haja complit tots, tanca la conversa amb naturalitat i acomiada''t.');
    END IF;

    INSERT INTO public.resources (id, name, type, category, content, difficulty, xp_earned, sort_order, metadata)
    VALUES (
      rid, r->>'name', r->>'type', r->>'category', r->>'content', 'C1', 15, (r->>'sort_order')::smallint,
      jsonb_build_object('icon', r->>'icon', 'color', r->>'color', 'section_name', r->>'title') || m
    )
    ON CONFLICT (id) DO UPDATE SET
      name = EXCLUDED.name,
      type = EXCLUDED.type,
      category = EXCLUDED.category,
      content = EXCLUDED.content,
      difficulty = EXCLUDED.difficulty,
      xp_earned = EXCLUDED.xp_earned,
      sort_order = EXCLUDED.sort_order,
      -- Conserva la lliçó fixa («Aprendre lliçó»), si una migració posterior n'hi afig.
      metadata = EXCLUDED.metadata || jsonb_strip_nulls(jsonb_build_object('lesson', resources.metadata -> 'lesson'));

    DELETE FROM public.practice_exercises WHERE resource_id = rid AND level = 'C1';
    DELETE FROM public.practice_passages WHERE resource_id = rid AND level = 'C1';

    ppos := 0;
    epos := 0;
    FOR b IN SELECT * FROM jsonb_array_elements(
      coalesce(r->'blocks', CASE WHEN r ? 'exercises' THEN jsonb_build_array(jsonb_build_object('exercises', r->'exercises')) ELSE '[]' END)
    ) LOOP
      pid := NULL;
      IF b ? 'passage' THEN
        ppos := ppos + 1;
        INSERT INTO public.practice_passages (resource_id, level, position, media, title, lines, audio_url)
        VALUES (
          rid, 'C1', ppos, b->'passage'->>'media', b->'passage'->>'title', b->'passage'->'lines',
          CASE WHEN b->'passage'->>'media' = 'audio' THEN format('/audio/practice/%s-c1-%s.wav', r->>'type', ppos) END
        )
        RETURNING id INTO pid;
      END IF;

      FOR e IN SELECT * FROM jsonb_array_elements(b->'exercises') LOOP
        epos := epos + 1;
        INSERT INTO public.practice_exercises (resource_id, level, position, passage_id, kind, prompt, options, answers, task, explanation)
        VALUES (
          rid, 'C1', epos, pid,
          CASE WHEN e ? 'o' THEN 'choice' WHEN e ? 'a' THEN 'fill' WHEN e ? 'w' THEN 'writing' ELSE 'form' END,
          e->>'q',
          CASE WHEN e ? 'o' THEN ARRAY(SELECT jsonb_array_elements_text(e->'o')) END,
          CASE WHEN e ? 'o' THEN ARRAY[e->'o'->>0] WHEN e ? 'a' THEN ARRAY(SELECT jsonb_array_elements_text(e->'a')) END,
          CASE WHEN e ? 'w' THEN e->'w' WHEN e ? 'f' THEN jsonb_build_object('fields', e->'f') END,
          e->>'e'
        );
      END LOOP;
    END LOOP;
  END LOOP;
END
$do$;
